INSERT INTO i18n_strings (lang_code, section, content) VALUES ('et', 'page:about-us-suppliers', '{"meta":{"title":"Koostööpartneritele | EstNor","desc":"EstNor otsib koostööpartnereid ehitusettevõtete, arendajate ja vahendajate seas."},"hero":{"crumb_home":"Avaleht","crumb_parent":"Ettevõttest","eyebrow":"Usaldusväärsed partnerid","h1":"Koostööpartneritele","lead":"EstNor otsib koostööpartnereid ehitusettevõtete, arendajate ja vahendajate seas. Koostööhuvi korral palume võtta ühendust."},"cards":[{"title":"Materjalid","desc":"Jätkusuutlikult hangitud puit ja ehitusmaterjalid, sh soojustusvill ja energiatõhusad PVC aknad."},{"title":"Logistika","desc":"Transpordipartnerid, kes veavad valmis elemendid ja moodulid Kiilist üle Läänemere ja maismaad pidi objektile."},{"title":"Sertifitseerimine","desc":"ISO 9001 kvaliteedijuhtimine ja Euroopa tehniline hinnang (ETA) tagavad ühtlase kvaliteedi."}],"memberships":{"eyebrow":"Liikmesused","h2":"Erialaliidud","items":["Eesti Puitmajaliit","Kiili Ettevõtjate Liit","Eesti-Norra Kaubanduskoda"]},"cta":{"h2":"Soovid koostööd teha?","body":"Kirjuta meile oma ettevõttest ja huvist — vastame esimesel võimalusel.","button":"Võta ühendust"}}') ON DUPLICATE KEY UPDATE content = VALUES(content);
INSERT INTO i18n_strings (lang_code, section, content) VALUES ('en', 'page:about-us-suppliers', '{"meta":{"title":"Suppliers & Co-operators — EstNor","desc":"EstNor\'s material suppliers, logistics partners and certification bodies supporting its timber house and facade element production."},"hero":{"crumb_home":"Home","crumb_parent":"About Us","eyebrow":"Built on trusted partnerships","h1":"Who EstNor builds with","lead":"Quality timber construction depends on a reliable network of material suppliers, logistics partners and certification bodies — for new houses and for facade renovation elements alike."},"cards":[{"title":"Timber & materials","desc":"Sustainably sourced pine and construction materials, including mineral wool insulation and energy-efficient PVC windows, meeting EU building standards."},{"title":"Logistics partners","desc":"Shipping and haulage partners moving completed elements and modules from Kiili across the Baltic Sea and overland — within the EU, without customs formalities."},{"title":"Certification bodies","desc":"ISO 9001 quality management, CE marking and European Technical Assessment (EOTA), plus the Ü-mark for use in Germany."}],"memberships":{"eyebrow":"Memberships","h2":"Industry & trade bodies","items":["Estonian Woodhouse Association (Puitmajaliit)","Kiili Entrepreneurs Union","Norwegian-Estonian Chamber of Commerce"]},"cta":{"h2":"Building with EstNor?","body":"Ask your project contact about our suppliers, certification, and logistics for your specific market.","button":"Get in touch"}}') ON DUPLICATE KEY UPDATE content = VALUES(content);
INSERT INTO i18n_strings (lang_code, section, content) VALUES ('de', 'page:about-us-suppliers', '{"meta":{"title":"Lieferanten & Partner | EstNor","desc":"EstNor sucht Kooperationspartner unter Bauunternehmen, Bauträgern und Vermittlern."},"hero":{"crumb_home":"Startseite","crumb_parent":"Über EstNor","eyebrow":"Verlässliche Partnerschaften","h1":"Lieferanten & Partner","lead":"EstNor sucht Kooperationspartner unter Bauunternehmen, Bauträgern und Vermittlern. Bei Interesse an einer Zusammenarbeit freuen wir uns über Ihre Kontaktaufnahme."},"cards":[{"title":"Materialien","desc":"Nachhaltig bezogenes Holz und Baumaterialien, einschließlich Mineralwolldämmung und energieeffizienter PVC-Fenster."},{"title":"Logistik","desc":"Transportpartner, die fertige Elemente und Module von Kiili über die Ostsee und auf dem Landweg zur Baustelle bringen."},{"title":"Zertifizierung","desc":"ISO-9001-Qualitätsmanagement und Europäische Technische Bewertung (ETA) sichern gleichbleibende Qualität."}],"memberships":{"eyebrow":"Mitgliedschaften","h2":"Verbände","items":["Estnischer Holzhausverband (Puitmajaliit)","Unternehmerverband Kiili","Estnisch-Norwegische Handelskammer"]},"cta":{"h2":"Interesse an einer Zusammenarbeit?","body":"Schreiben Sie uns kurz zu Ihrem Unternehmen und Ihrem Anliegen — wir melden uns zeitnah.","button":"Kontakt aufnehmen"}}') ON DUPLICATE KEY UPDATE content = VALUES(content);
INSERT INTO i18n_strings (lang_code, section, content) VALUES ('sv', 'page:about-us-suppliers', '{"meta":{"title":"Leverantörer & partners | EstNor","desc":"EstNor söker samarbetspartners bland byggföretag, byggherrar och förmedlare."},"hero":{"crumb_home":"Startsida","crumb_parent":"Om EstNor","eyebrow":"Pålitliga partnerskap","h1":"Leverantörer & partners","lead":"EstNor söker samarbetspartners bland byggföretag, byggherrar och förmedlare. Vid intresse för samarbete är ni välkomna att kontakta oss."},"cards":[{"title":"Material","desc":"Hållbart producerat virke och byggmaterial, inklusive mineralullsisolering och energieffektiva PVC-fönster."},{"title":"Logistik","desc":"Transportpartners som fraktar färdiga element och moduler från Kiili över Östersjön och landvägen till byggplatsen."},{"title":"Certifiering","desc":"ISO 9001-kvalitetsledning och europeisk teknisk bedömning (ETA) säkerställer jämn kvalitet."}],"memberships":{"eyebrow":"Medlemskap","h2":"Branschorganisationer","items":["Estniska Trähusförbundet (Puitmajaliit)","Kiili Företagarförening","Estnisk-Norska Handelskammaren"]},"cta":{"h2":"Intresserad av samarbete?","body":"Skriv kort om ert företag och intresse — vi återkommer inom kort.","button":"Kontakta oss"}}') ON DUPLICATE KEY UPDATE content = VALUES(content);
INSERT INTO i18n_strings (lang_code, section, content) VALUES ('nb', 'page:about-us-suppliers', '{"meta":{"title":"Leverandører & partnere | EstNor","desc":"EstNor søker samarbeidspartnere blant byggefirmaer, utbyggere og formidlere."},"hero":{"crumb_home":"Forsiden","crumb_parent":"Om EstNor","eyebrow":"Pålitelige partnerskap","h1":"Leverandører & partnere","lead":"EstNor søker samarbeidspartnere blant byggefirmaer, utbyggere og formidlere. Ved interesse for samarbeid tar dere gjerne kontakt med oss."},"cards":[{"title":"Materialer","desc":"Bærekraftig anskaffet trevirke og byggematerialer, inkludert mineralullisolasjon og energieffektive PVC-vinduer."},{"title":"Logistikk","desc":"Transportpartnere som frakter ferdige elementer og moduler fra Kiili over Østersjøen og på land til byggeplassen."},{"title":"Sertifisering","desc":"ISO 9001-kvalitetsstyring og europeisk teknisk vurdering (ETA) sikrer jevn kvalitet."}],"memberships":{"eyebrow":"Medlemskap","h2":"Bransjeforeninger","items":["Estisk Trehusforening (Puitmajaliit)","Kiili Næringsforening","Estisk-Norsk Handelskammer"]},"cta":{"h2":"Interessert i samarbeid?","body":"Skriv kort om selskapet deres og interessen — vi svarer så snart som mulig.","button":"Kontakt oss"}}') ON DUPLICATE KEY UPDATE content = VALUES(content);
INSERT INTO i18n_strings (lang_code, section, content) VALUES ('et', 'page:about-us', '{"meta":{"title":"Ettevõttest | EstNor","desc":"EstNor OÜ on Eesti kapitalil tegutsev ettevõte, mis on asutatud 2000. aastal ja toodab element-, moodul- ning palkmaju Kiilis ja Jõgevamaal."},"hero":{"crumb":"Avaleht","eyebrow":"Ettevõttest","h1":"Üle 20 aasta kogemust puitehituses","lead":"EstNor OÜ on Eesti kapitalil tegutsev ettevõte, mille põhitegevusalaks on puitmajade tootmine ja püstitamine. Element- ja moodulmajatehas asub Kiili vallas, Harjumaal, palkmajatehas Jõgevamaal."},"stats":[{"value":"25","label":"aastat kogemust"},{"value":"1000+","label":"toodetud elamuühikut"},{"value":"~50","label":"maja aastas, ~10 000 m²"},{"value":"90%","label":"eksport, peamiselt Norrasse"}],"who":{"eyebrow":"Ettevõttest","h2":"Kes me oleme","paragraphs":["EstNor OÜ on asutatud 2000. aastal. Üheksateistkümne aasta jooksul on ehitatud üle 1000 elamuühiku — peamine eksporditurg on Norra, kuhu on tarnitud ca 90% toodangust, järgnevad Rootsi, Eesti, Soome ja Saksamaa.","EstNor OÜ klientideks on ehitusettevõtted, arendajad, vahendajad ja eraisikud."]},"memberships":{"eyebrow":"Liikmesused ja tunnustused","items":["Eesti Puitmajaliidu liige (alates 2009)","Kiili Ettevõtjate Liidu liige (alates 2004)","Eesti-Norra Kaubanduskoja liige","Gasellettevõte 2015 ja 2016 — tunnustus, mida kannab vaid 1% Eesti ettevõtetest","Aasta Tehasemaja konkursi tunnustused 2015, 2017, 2018 ja 2019"]},"history":{"eyebrow":"Lühiajalugu","h2":"Kuidas EstNor on kasvanud","timeline":[{"year":"2000","text":"EstNor OÜ asutatakse 20. oktoobril ja soetatakse Kiilis asuv tootmishoone."},{"year":"2001","text":"Valmib esimene palkmaja — tehase esimene toodang."},{"year":"2004","text":"Lisaks palkmajadele alustatakse palkkarkassmajade tootmisega; EstNor liitub Kiili Ettevõtjate Liiduga."},{"year":"2006","text":"Algab elementmajade tootmine; asutatakse kinnisvaraettevõte EstNor Arendus OÜ."},{"year":"2009","text":"EstNor liitub Eesti Puitmajaliiduga."},{"year":"2012","text":"Kiilis valmib uus büroo- ja tootmishoone."},{"year":"2015","text":"Käivitatakse uus majatehas Kiilis, väljastatakse ISO 9001 sertifikaat ja alustatakse moodulmajade tootmisega."},{"year":"2018","text":"EstNor avab palkmajatehase Jõgevamaal; ettevõtte töötaja krooniti viiendat aastat järjest Eesti parimaks palkmajaehitajaks."},{"year":"2019","text":"EstNor OÜ-le väljastatakse Euroopa tehniline hinnang (ETA)."},{"year":"2022","text":"EstNor on esimene tootja, kes liitub riikliku KredEx tehaselise rekonstrueerimise pilootprogrammiga."}]},"certs":{"eyebrow":"Kvaliteet ja sertifikaadid","h2":"Sertifikaadid ja liikmesused","items":[{"text":"ISO 9001 kvaliteedijuhtimissüsteem (alates 2015)","pdf":null},{"text":"Euroopa tehniline hinnang (ETA, alates 2019)","pdf":null},{"text":"Eesti Puitmajaliidu liige","pdf":null},{"text":"Majad toodetakse SINTEF ehitusnormide järgi; Norra turul TEK 10, passiivmajadel TEK 15 nõuete kohaselt","pdf":null}],"pdf_label":"Laadi alla PDF"},"registry":{"eyebrow":"Ettevõtte andmed","h2":"Registriandmed","rows":[{"label":"Ärinimi","value":"EstNor OÜ"},{"label":"Registrikood","value":"10706304"},{"label":"KMKR nr","value":"EE100650305"},{"label":"Juhatuse liige","value":"Renee Mikomägi"}]},"explore":{"eyebrow":"Rohkem infot","h2":"Jätka lugemist","cards":[{"title":"Tootmine","desc":"Pilguheit tehasesse — elementide ja fassaadidetailide valmistamine.","href":"production.php"},{"title":"Tehaseline renoveerimine","desc":"Kuidas EstNor fassaadielemendid aitavad kortermaju energiatõhusaks muuta.","href":"../serial-renovation/index.php"}]}}') ON DUPLICATE KEY UPDATE content = VALUES(content);
INSERT INTO i18n_strings (lang_code, section, content) VALUES ('de', 'page:about-us', '{"meta":{"title":"Über EstNor | EstNor","desc":"EstNor OÜ ist ein estnisches Unternehmen, gegründet 2000, mit Werken in Kiili (Element- und Modulhäuser) und Jõgevamaa (Blockhäuser)."},"hero":{"crumb":"Startseite","eyebrow":"Über EstNor","h1":"Über 20 Jahre Erfahrung im Holzbau","lead":"EstNor OÜ ist ein estnisches Unternehmen mit eigener Hausfabrik in Kiili sowie einem Blockhauswerk in Jõgevamaa. Der Schwerpunkt liegt auf der Fertigung von Holzhäusern."},"stats":[{"value":"25","label":"Jahre Erfahrung"},{"value":"1.000+","label":"errichtete Wohneinheiten"},{"value":"~50","label":"Häuser pro Jahr, ~10.000 m²"},{"value":"90 %","label":"Exportanteil, vor allem nach Norwegen"}],"who":{"eyebrow":"Wer wir sind","h2":"Unser Unternehmen","paragraphs":["EstNor OÜ wurde im Jahr 2000 gegründet. In über zwei Jahrzehnten wurden mehr als 1.000 Wohneinheiten gebaut — der wichtigste Exportmarkt ist Norwegen mit rund 90 % der Produktion, gefolgt von Schweden, Estland, Finnland und Deutschland.","Zu den Kunden von EstNor OÜ zählen Bauunternehmen, Bauträger, Vermittler und Privatpersonen."]},"memberships":{"eyebrow":"Mitgliedschaften & Auszeichnungen","items":["Mitglied im Estnischen Holzhausverband (seit 2009)","Mitglied im Unternehmerverband Kiili (seit 2004)","Mitglied der Estnisch-Norwegischen Handelskammer","Gazellenunternehmen 2015 und 2016 — eine Auszeichnung, die nur 1 % der estnischen Unternehmen tragen","Auszeichnungen im Wettbewerb „Hausfabrik des Jahres\\" 2015, 2017, 2018 und 2019"]},"history":{"eyebrow":"Kurze Geschichte","h2":"Wie EstNor gewachsen ist","timeline":[{"year":"2000","text":"EstNor OÜ wird am 20. Oktober gegründet; die Produktionshalle in Kiili wird erworben."},{"year":"2001","text":"Das erste Blockhaus verlässt das neue Werk."},{"year":"2004","text":"Zusätzlich zu Blockhäusern startet die Fertigung von Pfosten-Riegel-Blockhäusern; EstNor tritt dem Unternehmerverband Kiili bei."},{"year":"2006","text":"Die Elementhaus-Fertigung beginnt; die Immobiliengesellschaft EstNor Arendus OÜ wird gegründet."},{"year":"2009","text":"EstNor tritt dem Estnischen Holzhausverband bei."},{"year":"2012","text":"Ein neues Büro- und Produktionsgebäude entsteht in Kiili."},{"year":"2015","text":"Ein neues Hauswerk in Kiili geht in Betrieb, die ISO-9001-Zertifizierung wird erteilt, und die Modulhaus-Fertigung startet."},{"year":"2018","text":"EstNor eröffnet ein Blockhauswerk in Jõgevamaa; ein EstNor-Mitarbeiter wird zum fünften Mal in Folge zum besten Blockhausbauer Estlands gekürt."},{"year":"2019","text":"EstNor OÜ erhält die Europäische Technische Bewertung (ETA)."},{"year":"2022","text":"EstNor wird erster Hersteller im staatlichen KredEx-Pilotprogramm für serielle Sanierung."}]},"certs":{"eyebrow":"Qualität & Zertifizierung","h2":"Zertifikate & Mitgliedschaften","items":[{"text":"Qualitätsmanagement nach ISO 9001 (seit 2015)","pdf":null},{"text":"Europäische Technische Bewertung (ETA, seit 2019)","pdf":null},{"text":"Mitglied im Estnischen Holzhausverband","pdf":null},{"text":"Fertigung nach SINTEF-Baunormen; auf dem norwegischen Markt nach TEK 10, bei Passivhäusern nach TEK 15","pdf":null}],"pdf_label":"PDF herunterladen"},"registry":{"eyebrow":"Unternehmensdaten","h2":"Registerdaten","rows":[{"label":"Firmenname","value":"EstNor OÜ"},{"label":"Registrikood","value":"10706304"},{"label":"USt-IdNr.","value":"EE100650305"},{"label":"Geschäftsführer","value":"Renee Mikomägi"}]},"explore":{"eyebrow":"Mehr erfahren","h2":"Weiterlesen","cards":[{"title":"Produktion","desc":"Ein Blick in die Fabrik — wie Elemente und Fassadenteile entstehen.","href":"production.php"},{"title":"Serielle Sanierung","desc":"Wie EstNor-Fassadenelemente Mehrfamilienhäuser energieeffizient machen.","href":"../serial-renovation/index.php"}]}}') ON DUPLICATE KEY UPDATE content = VALUES(content);
INSERT INTO i18n_strings (lang_code, section, content) VALUES ('sv', 'page:about-us', '{"meta":{"title":"Om EstNor | EstNor","desc":"EstNor OÜ är ett estniskt företag, grundat 2000, med fabriker i Kiili (element- och modulhus) och Jõgevamaa (timmerhus)."},"hero":{"crumb":"Startsida","eyebrow":"Om EstNor","h1":"Över 20 års erfarenhet av trähusbyggande","lead":"EstNor OÜ är ett estniskt företag med egen husfabrik i Kiili samt en timmerhusfabrik i Jõgevamaa. Huvudverksamheten är tillverkning av trähus."},"stats":[{"value":"25","label":"års erfarenhet"},{"value":"1 000+","label":"byggda bostäder"},{"value":"~50","label":"hus per år, ~10 000 m²"},{"value":"90 %","label":"export, främst till Norge"}],"who":{"eyebrow":"Vilka vi är","h2":"Vårt företag","paragraphs":["EstNor OÜ grundades år 2000. Under drygt två decennier har över 1 000 bostäder byggts — Norge är den viktigaste exportmarknaden med cirka 90 % av produktionen, följt av Sverige, Estland, Finland och Tyskland.","EstNors kunder är byggföretag, byggherrar, förmedlare och privatpersoner."]},"memberships":{"eyebrow":"Medlemskap & utmärkelser","items":["Medlem i Estniska Trähusförbundet (sedan 2009)","Medlem i Kiili Företagarförening (sedan 2004)","Medlem i Estnisk-Norska Handelskammaren","Gasellföretag 2015 och 2016 — en utmärkelse som endast 1 % av estniska företag bär","Utmärkelser i tävlingen \\"Årets husfabrik\\" 2015, 2017, 2018 och 2019"]},"history":{"eyebrow":"Kort historik","h2":"Hur EstNor har vuxit","timeline":[{"year":"2000","text":"EstNor OÜ grundas den 20 oktober; produktionsbyggnaden i Kiili förvärvas."},{"year":"2001","text":"Det första timmerhuset lämnar den nya fabriken."},{"year":"2004","text":"Utöver timmerhus inleds tillverkning av timmerhus med regelverk; EstNor blir medlem i Kiili Företagarförening."},{"year":"2006","text":"Tillverkning av elementhus inleds; fastighetsbolaget EstNor Arendus OÜ grundas."},{"year":"2009","text":"EstNor blir medlem i Estniska Trähusförbundet."},{"year":"2012","text":"En ny kontors- och produktionsbyggnad uppförs i Kiili."},{"year":"2015","text":"En ny husfabrik i Kiili tas i drift, ISO 9001-certifiering utfärdas och produktionen av modulhus inleds."},{"year":"2018","text":"EstNor öppnar en timmerhusfabrik i Jõgevamaa; en EstNor-medarbetare koras för femte året i rad till Estlands bästa timmerhusbyggare."},{"year":"2019","text":"EstNor OÜ tilldelas en europeisk teknisk bedömning (ETA)."},{"year":"2022","text":"EstNor blir första tillverkare i det statliga KredEx-pilotprogrammet för seriell renovering."}]},"certs":{"eyebrow":"Kvalitet & certifiering","h2":"Certifikat & medlemskap","items":[{"text":"Kvalitetsledning enligt ISO 9001 (sedan 2015)","pdf":null},{"text":"Europeisk teknisk bedömning (ETA, sedan 2019)","pdf":null},{"text":"Medlem i Estniska Trähusförbundet","pdf":null},{"text":"Tillverkning enligt SINTEF-byggnormer; på den norska marknaden enligt TEK 10, för passivhus TEK 15","pdf":null}],"pdf_label":"Ladda ner PDF"},"registry":{"eyebrow":"Företagsuppgifter","h2":"Registeruppgifter","rows":[{"label":"Firmanamn","value":"EstNor OÜ"},{"label":"Registrikood","value":"10706304"},{"label":"Momsregistreringsnummer","value":"EE100650305"},{"label":"Styrelseledamot","value":"Renee Mikomägi"}]},"explore":{"eyebrow":"Läs mer","h2":"Fortsätt utforska","cards":[{"title":"Produktion","desc":"En titt inne i fabriken — hur element och fasaddelar tillverkas.","href":"production.php"},{"title":"Modernisering av flerbostadshus","desc":"Hur EstNors fasadelement gör flerbostadshus energieffektiva.","href":"../serial-renovation/index.php"}]}}') ON DUPLICATE KEY UPDATE content = VALUES(content);
INSERT INTO i18n_strings (lang_code, section, content) VALUES ('nb', 'page:about-us', '{"meta":{"title":"Om EstNor | EstNor","desc":"EstNor OÜ er et estisk selskap, grunnlagt i 2000, med fabrikker i Kiili (element- og modulhus) og Jõgevamaa (tømmerhus)."},"hero":{"crumb":"Forsiden","eyebrow":"Om EstNor","h1":"Over 20 års erfaring med trehusbygging","lead":"EstNor OÜ er et estisk selskap med egen husfabrikk i Kiili samt en tømmerhusfabrikk i Jõgevamaa. Hovedvirksomheten er produksjon av trehus."},"stats":[{"value":"25","label":"års erfaring"},{"value":"1000+","label":"bygde boenheter"},{"value":"~50","label":"hus per år, ~10 000 m²"},{"value":"90 %","label":"eksport, hovedsakelig til Norge"}],"who":{"eyebrow":"Hvem vi er","h2":"Vårt selskap","paragraphs":["EstNor OÜ ble grunnlagt i 2000. I løpet av over to tiår er det bygget over 1000 boenheter — Norge er det viktigste eksportmarkedet med rundt 90 % av produksjonen, etterfulgt av Sverige, Estland, Finland og Tyskland.","EstNors kunder er byggefirmaer, utbyggere, formidlere og privatpersoner."]},"memberships":{"eyebrow":"Medlemskap & utmerkelser","items":["Medlem av Estisk Trehusforening (siden 2009)","Medlem av Kiili Næringsforening (siden 2004)","Medlem av Estisk-Norsk Handelskammer","Gasellebedrift 2015 og 2016 — en utmerkelse kun 1 % av estiske selskaper har","Utmerkelser i konkurransen «Årets husfabrikk» 2015, 2017, 2018 og 2019"]},"history":{"eyebrow":"Kort historie","h2":"Hvordan EstNor har vokst","timeline":[{"year":"2000","text":"EstNor OÜ stiftes 20. oktober; produksjonsbygget i Kiili anskaffes."},{"year":"2001","text":"Det første tømmerhuset forlater den nye fabrikken."},{"year":"2004","text":"I tillegg til tømmerhus starter produksjon av reisverkshus; EstNor blir medlem av Kiili Næringsforening."},{"year":"2006","text":"Produksjon av elementhus starter; eiendomsselskapet EstNor Arendus OÜ stiftes."},{"year":"2009","text":"EstNor blir medlem av Estisk Trehusforening."},{"year":"2012","text":"Et nytt kontor- og produksjonsbygg reises i Kiili."},{"year":"2015","text":"En ny husfabrikk i Kiili settes i drift, ISO 9001-sertifisering utstedes, og produksjon av modulhus starter."},{"year":"2018","text":"EstNor åpner en tømmerhusfabrikk i Jõgevamaa; en EstNor-ansatt kåres for femte år på rad til Estlands beste tømmerhusbygger."},{"year":"2019","text":"EstNor OÜ tildeles europeisk teknisk vurdering (ETA)."},{"year":"2022","text":"EstNor blir første produsent i det statlige KredEx-pilotprogrammet for seriell rehabilitering."}]},"certs":{"eyebrow":"Kvalitet & sertifisering","h2":"Sertifikater & medlemskap","items":[{"text":"Kvalitetsstyring etter ISO 9001 (siden 2015)","pdf":null},{"text":"Europeisk teknisk vurdering (ETA, siden 2019)","pdf":null},{"text":"Medlem av Estisk Trehusforening","pdf":null},{"text":"Produksjon etter SINTEF-byggenormer; på det norske markedet etter TEK 10, for passivhus TEK 15","pdf":null}],"pdf_label":"Last ned PDF"},"registry":{"eyebrow":"Selskapsopplysninger","h2":"Registeropplysninger","rows":[{"label":"Firmanavn","value":"EstNor OÜ"},{"label":"Registrikood","value":"10706304"},{"label":"MVA-nummer","value":"EE100650305"},{"label":"Styremedlem","value":"Renee Mikomägi"}]},"explore":{"eyebrow":"Les mer","h2":"Fortsett å utforske","cards":[{"title":"Produksjon","desc":"Et innblikk i fabrikken — hvordan elementer og fasadedeler produseres.","href":"production.php"},{"title":"Modernisering av leilighetsbygg","desc":"Hvordan EstNors fasadeelementer gjør leilighetsbygg energieffektive.","href":"../serial-renovation/index.php"}]}}') ON DUPLICATE KEY UPDATE content = VALUES(content);
INSERT INTO i18n_strings (lang_code, section, content) VALUES ('en', 'page:about-us', '{"meta":{"title":"About EstNor | EstNor","desc":"EstNor OÜ is an Estonian company founded in 2000, with factories in Kiili (element and modular houses) and Jõgevamaa (log houses)."},"hero":{"crumb":"Home","eyebrow":"About EstNor","h1":"Over 20 years of experience in timber construction","lead":"EstNor OÜ is an Estonian company whose core business is manufacturing and erecting timber houses. The element and modular house factory is in Kiili, Harju County, with a separate log-house factory in Jõgevamaa."},"stats":[{"value":"25","label":"years of experience"},{"value":"1,000+","label":"residential units produced"},{"value":"~50","label":"houses a year, ~10,000 m²"},{"value":"90%","label":"export, mainly to Norway"}],"who":{"eyebrow":"Who we are","h2":"Our company","paragraphs":["EstNor OÜ was founded in 2000. Over more than two decades it has built over 1,000 residential units — the main export market is Norway, taking around 90% of production, followed by Sweden, Estonia, Finland and Germany.","EstNor OÜ\'s customers include construction companies, developers, intermediaries and private individuals."]},"memberships":{"eyebrow":"Memberships & recognition","items":["Member of the Estonian Woodhouse Association (since 2009)","Member of the Kiili Entrepreneurs Union (since 2004)","Member of the Estonian-Norwegian Chamber of Commerce","Gazelle company 2015 and 2016 — a distinction held by only 1% of Estonian companies","\\"Factory House of the Year\\" competition recognitions in 2015, 2017, 2018 and 2019"]},"history":{"eyebrow":"Brief history","h2":"How EstNor has grown","timeline":[{"year":"2000","text":"EstNor OÜ is founded on 20 October; the production building in Kiili is acquired."},{"year":"2001","text":"The first log house leaves the new factory — the factory\'s first output."},{"year":"2004","text":"Alongside log houses, production of post-and-beam log houses begins; EstNor joins the Kiili Entrepreneurs Union."},{"year":"2006","text":"Element house production begins; the real-estate company EstNor Arendus OÜ is founded."},{"year":"2009","text":"EstNor joins the Estonian Woodhouse Association."},{"year":"2012","text":"A new office and production building is completed in Kiili."},{"year":"2015","text":"A new house factory starts up in Kiili, ISO 9001 certification is issued, and modular house production begins."},{"year":"2018","text":"EstNor opens a log-house factory in Jõgevamaa; an EstNor employee is named Estonia\'s best log-house builder for the fifth year running."},{"year":"2019","text":"EstNor OÜ receives its European Technical Assessment (ETA)."},{"year":"2022","text":"EstNor becomes the first manufacturer to join the state KredEx pilot programme for serial renovation."}]},"certs":{"eyebrow":"Quality & certification","h2":"Certificates & memberships","items":[{"text":"Quality management to ISO 9001 (since 2015)","pdf":null},{"text":"European Technical Assessment (ETA, since 2019)","pdf":null},{"text":"Member of the Estonian Woodhouse Association","pdf":null},{"text":"Manufactured to SINTEF building standards; to TEK 10 for the Norwegian market, TEK 15 for passive houses","pdf":null}],"pdf_label":"Download PDF"},"registry":{"eyebrow":"Company data","h2":"Registration details","rows":[{"label":"Legal name","value":"EstNor OÜ"},{"label":"Registry code","value":"10706304"},{"label":"VAT ID","value":"EE100650305"},{"label":"Board member","value":"Renee Mikomägi"}]},"explore":{"eyebrow":"Learn more","h2":"Keep exploring","cards":[{"title":"Production","desc":"A look inside the factory — how elements and facade parts are made.","href":"production.php"},{"title":"Serial Renovation","desc":"How EstNor\'s facade elements help apartment buildings become energy efficient.","href":"../serial-renovation/index.php"}]}}') ON DUPLICATE KEY UPDATE content = VALUES(content);
INSERT INTO i18n_strings (lang_code, section, content) VALUES ('et', 'page:contact', '{"meta":{"title":"Kontakt | EstNor","desc":"Kontakt EstNor OÜ — Kurna tee 33, Kiili, 75401 Harjumaa. Telefon +372 651 6174, e-post info@estnor.ee."},"hero":{"crumb":"Avaleht","label":"Kontakt","eyebrow":"Kontakt","h1":"Räägime sinu projektist","lead":"Olgu tegu uue majaga või kortermaja tehaselise renoveerimisega — saada meile hoone põhiandmed ja anname esialgse hinnangu."},"contact_heading":"Kontaktandmed","labels":{"email":"E-post","phone":"Telefon","fax":"Faks","address":"Aadress"},"address_lines":["EstNor OÜ","Kurna tee 33, 75401 Kiili","Sepamäe tee 3, Kiili vald","Harjumaa, Eesti"],"registry_note":"Registrikood 10706304 · KMKR nr EE100650305.","office_hours":"Vastame E–R kell 8–17. Hea meelega leppime kokku kohtumise või tagasihelistamise.","map_title":"EstNori asukoht kaardil","form_heading":"Saada sõnum","form":{"name":"Nimi *","company":"Ettevõte","email":"E-post *","phone":"Telefon","subject":"Teema","message":"Sõnum *","hp":"Jäta tühjaks","submit":"Saada sõnum"},"subject_options":["Elementmajad","Moodulmajad","Tehaseline renoveerimine / fassaadielemendid","Muu"],"form_note_pre":"See on staatiline näidisleht — vorm ei ole ühendatud meiliserveriga. Kirjuta otse ","form_note_post":"."}') ON DUPLICATE KEY UPDATE content = VALUES(content);
INSERT INTO i18n_strings (lang_code, section, content) VALUES ('en', 'page:contact', '{"meta":{"title":"Contact — EstNor","desc":"Contact EstNor — Kurna tee 33, Kiili, Harju County, Estonia. Phone +372 651 6174, email info@estnor.ee."},"hero":{"crumb":"Home","label":"Contact","eyebrow":"Contact","h1":"Let\'s talk about your project","lead":"Whether it\'s a new timber house or a serial facade renovation: send us the key details — building type, size, timeframe — and we\'ll come back with an initial assessment."},"contact_heading":"Contact details","labels":{"email":"Email","phone":"Phone","fax":"Fax","address":"Address"},"address_lines":["EstNor OÜ","Kurna tee 33, 75401 Kiili","Sepamäe tee 3, Kiili Parish","Harju County, Estonia"],"registry_note":"Registry code 10706304 · VAT EE100650305 — Estonian e-Business Register.","office_hours":"Office hours: Mon–Fri, 08:00–17:00 EET. We\'re happy to arrange a meeting or a call back.","map_title":"EstNor location map","form_heading":"Send a message","form":{"name":"Full name *","company":"Company","email":"Email *","phone":"Phone","subject":"Subject","message":"Message *","hp":"Leave blank","submit":"Send message"},"subject_options":["Element houses","Modular houses","Serial renovation / facade elements","Something else"],"form_note_pre":"This is a static demo site — the form isn\'t wired to a mail server. Please email ","form_note_post":" directly."}') ON DUPLICATE KEY UPDATE content = VALUES(content);
INSERT INTO i18n_strings (lang_code, section, content) VALUES ('de', 'page:contact', '{"meta":{"title":"Kontakt | EstNor","desc":"Kontakt EstNor OÜ — Kurna tee 33, Kiili, 75401 Harjumaa, Estland. Telefon +372 651 6174, E-Mail info@estnor.ee."},"hero":{"crumb":"Startseite","label":"Kontakt","eyebrow":"Kontakt","h1":"Sprechen wir über Ihr Projekt","lead":"Ob Neubau oder serielle Fassadensanierung eines Mehrfamilienhauses: Schicken Sie uns die Eckdaten — wir melden uns mit einer ersten Einschätzung zurück."},"contact_heading":"Kontaktdaten","labels":{"email":"E-Mail","phone":"Telefon","fax":"Telefax","address":"Anschrift"},"address_lines":["EstNor OÜ","Kurna tee 33, 75401 Kiili","Sepamäe tee 3, Kiili vald","Harjumaa, Estland"],"registry_note":"Registrikood 10706304 · USt-IdNr. EE100650305.","office_hours":"Anfragen aus Deutschland beantwortet EstNor auf Deutsch. Gern vereinbaren wir einen Termin oder einen Rückruf.","map_title":"Standort von EstNor","form_heading":"Nachricht senden","form":{"name":"Name *","company":"Unternehmen","email":"E-Mail *","phone":"Telefon","subject":"Betreff","message":"Nachricht *","hp":"Bitte frei lassen","submit":"Absenden"},"subject_options":["Elementhäuser","Modulhäuser","Serielle Sanierung / Fassadenelemente","Sonstiges"],"form_note_pre":"Dies ist eine statische Demo-Seite — das Formular ist nicht mit einem Mailserver verbunden. Bitte schreiben Sie direkt an ","form_note_post":"."}') ON DUPLICATE KEY UPDATE content = VALUES(content);
INSERT INTO i18n_strings (lang_code, section, content) VALUES ('sv', 'page:contact', '{"meta":{"title":"Kontakt | EstNor","desc":"Kontakta EstNor OÜ — Kurna tee 33, Kiili, 75401 Harjumaa, Estland. Telefon +372 651 6174, e-post info@estnor.ee."},"hero":{"crumb":"Startsida","label":"Kontakt","eyebrow":"Kontakt","h1":"Låt oss diskutera ert projekt","lead":"Oavsett om det gäller ett nytt trähus eller seriell fasadrenovering av ett flerbostadshus: skicka oss nyckeltalen så återkommer vi med en första bedömning."},"contact_heading":"Kontaktuppgifter","labels":{"email":"E-post","phone":"Telefon","fax":"Fax","address":"Adress"},"address_lines":["EstNor OÜ","Kurna tee 33, 75401 Kiili","Sepamäe tee 3, Kiili vald","Harjumaa, Estland"],"registry_note":"Registrikood 10706304 · Momsregistreringsnummer EE100650305.","office_hours":"Vi svarar måndag–fredag kl. 8–17. Vi bokar gärna in ett möte eller en återuppringning.","map_title":"EstNors adress på kartan","form_heading":"Skicka ett meddelande","form":{"name":"Namn *","company":"Företag","email":"E-post *","phone":"Telefon","subject":"Ämne","message":"Meddelande *","hp":"Lämna tomt","submit":"Skicka"},"subject_options":["Elementhus","Modulhus","Modernisering / fasadelement","Annat"],"form_note_pre":"Detta är en statisk demosida — formuläret är inte kopplat till en e-postserver. Skriv gärna direkt till ","form_note_post":"."}') ON DUPLICATE KEY UPDATE content = VALUES(content);
INSERT INTO i18n_strings (lang_code, section, content) VALUES ('nb', 'page:contact', '{"meta":{"title":"Kontakt | EstNor","desc":"Kontakt EstNor OÜ — Kurna tee 33, Kiili, 75401 Harjumaa, Estland. Telefon +372 651 6174, e-post info@estnor.ee."},"hero":{"crumb":"Forsiden","label":"Kontakt","eyebrow":"Kontakt","h1":"La oss snakke om prosjektet ditt","lead":"Enten det er et nytt trehus eller seriell fasaderehabilitering av et leilighetsbygg: send oss nøkkeltallene, så kommer vi tilbake med en første vurdering."},"contact_heading":"Kontaktinformasjon","labels":{"email":"E-post","phone":"Telefon","fax":"Faks","address":"Adresse"},"address_lines":["EstNor OÜ","Kurna tee 33, 75401 Kiili","Sepamäe tee 3, Kiili vald","Harjumaa, Estland"],"registry_note":"Registrikood 10706304 · MVA-nummer EE100650305.","office_hours":"Vi svarer mandag–fredag kl. 8–17. Vi avtaler gjerne et møte eller en tilbakeringing.","map_title":"EstNors adresse på kartet","form_heading":"Send en melding","form":{"name":"Navn *","company":"Firma","email":"E-post *","phone":"Telefon","subject":"Emne","message":"Melding *","hp":"La stå tomt","submit":"Send"},"subject_options":["Elementhus","Modulhus","Modernisering / fasadeelementer","Annet"],"form_note_pre":"Dette er en statisk demoside — skjemaet er ikke koblet til en e-postserver. Skriv gjerne direkte til ","form_note_post":"."}') ON DUPLICATE KEY UPDATE content = VALUES(content);
INSERT INTO i18n_strings (lang_code, section, content) VALUES ('et', 'page:houses-element-houses', '{"meta":{"title":"Elementmaja | EstNor","desc":"EstNor OÜ toodab puitkarkass elementmaju Kiilis asuvas elementmajatehases — välis-, sise-, vahelae-, katuse- ja terrassielemendid."},"hero":{"crumb":"Avaleht","parent_label":"Majad","label":"Elementmaja","eyebrow":"Tehases toodetud","h1":"Elementmajast lähemalt","lead":"EstNor OÜ toodab puitkarkass elementmaju Kiilis asuvas elementmajatehases. Tehases toodetakse välis-, sise-, vahelae-, katuse- ja terrassielemendid."},"benefits":{"h2":"Elementmaja eelised","items":["Tehases toodetud maja on kvaliteetne — ehitus toimub kontrollitud siseruumides, ilma ilmastikukahjustusteta (vihm, lumi, tuul, temperatuur)","Ehitus on kiire — elementide monteerimine toimub spetsiaalsetel töölaudadel, mis on varustatud vajalike tööriistadega","Täpsed tööjoonised teevad tootmise kiireks ja efektiivseks — elemendid valmivad millimeetritäpsusega","Insenerid teostavad tugevusarvutused kohalike normide järgi, mis välistab alamõõtmestamise","Tehases ehitatakse valmis nii palju kui võimalik: soojustus, auru- ja tuuletõkkematerjalid, värvitud välisvoodrilaud, aknad, uksed","Objektil paigaldatakse elemendid kraanaga 1–5 päevaga, olenevalt maja suurusest"]},"capabilities":{"eyebrow":"Ilma suuremate piiranguteta","h2":"Sobib ka keerukale arhitektuurile","lead":"Erinevalt moodulmajadest saab elementmajana ehitada keerulise arhitektuuri ja suuremõõtmeliste ruumidega hooneid — sealhulgas kortermaju.","cards":[{"title":"Kraanapaigaldus","desc":"Elementide püstitus ja katuse ehitustööd."},{"title":"Avatäited","desc":"Akende, terrassi-, välis- ja siseuste paigaldus."},{"title":"Viimistlus","desc":"Põrandad, vahe- ja katuslaed, piirdeliistud, plaatimis- ja maalritööd."},{"title":"Terrass ja korsten","desc":"Terrassi paigaldustööd ning Schiedeli metall- ja moodulkorstnad."}]},"materials":{"eyebrow":"Materjalivalik","h2":"Valikuvõimalused (standardlahendused rasvases kirjas mujal kataloogis)","cards":[{"title":"Välisviimistlus","desc":"Voodrilaud 21×145 mm või 21×190 mm, poola laudis, servamata laud, fassaadiplaat."},{"title":"Aknad ja uksed","desc":"Kolmekordse klaasiga aknad (erineva avanemisega), energiasäästlik välisuks, MDF-siseuksed."},{"title":"Katusekate","desc":"Kivi-, plekk-, SBS- ja bituumenkatus, samuti laudis- ja mätaskatus."},{"title":"Põrandakate","desc":"Tammeparkett (1- või 3-lipiline), tammelaud või männist põrandalaud."},{"title":"Trepid","desc":"Männi- või tammeastmed, viimistletud või viimistlemata, puit- või klaaspiirded."},{"title":"Terrass","desc":"28×120 mm või 28×145 mm rihveldatud terrassilaud, pruun või roheline immutus."}]},"callout":{"label":"Õhu- ja tuulepidavus:","text":"EstNor kasutab valdkonna juhtiva ettevõtte SIGA tooteid — auru- ja tuuletõkkekangaid, teipe ja tihendusaineid. Majad toodetakse SINTEF ehitusnormide järgi; Norra turul järgitakse TEK 10, passiivmajadel TEK 15 nõudeid."},"cta":{"h2":"Planeerid suurt või keerukat ehitist?","body":"Elementmaja võib olla õige valik — räägi meiega oma projektist.","button":"Võta ühendust"}}') ON DUPLICATE KEY UPDATE content = VALUES(content);
INSERT INTO i18n_strings (lang_code, section, content) VALUES ('de', 'page:houses-element-houses', '{"meta":{"title":"Elementhaus | EstNor","desc":"EstNor OÜ fertigt Holzrahmen-Elementhäuser im Elementhauswerk in Kiili — Außen-, Innen-, Geschossdecken-, Dach- und Terrassenelemente."},"hero":{"crumb":"Startseite","parent_label":"Häuser","label":"Elementhaus","eyebrow":"Werksgefertigt","h1":"Das Elementhaus im Detail","lead":"EstNor OÜ fertigt Holzrahmen-Elementhäuser im Elementhauswerk in Kiili. Im Werk entstehen Außen-, Innen-, Geschossdecken-, Dach- und Terrassenelemente."},"benefits":{"h2":"Vorteile des Elementhauses","items":["Werksgefertigte Häuser sind hochwertig — der Bau erfolgt in einer kontrollierten Innenumgebung, ohne Witterungsschäden (Regen, Schnee, Wind, Temperatur)","Schneller Bau — die Montage der Elemente erfolgt an speziellen Werkbänken mit dem nötigen Werkzeug","Präzise Werkzeichnungen machen die Fertigung schnell und effizient — Elemente entstehen millimetergenau","Ingenieure führen Tragfähigkeitsberechnungen nach lokalen Normen durch, wodurch eine Unterdimensionierung ausgeschlossen ist","Im Werk wird so viel wie möglich fertiggestellt: Dämmung, Dampf- und Windsperre, lackierte Außenverkleidung, Fenster, Türen","Vor Ort werden die Elemente je nach Haushöhe in 1–5 Tagen per Kran montiert"]},"capabilities":{"eyebrow":"Ohne wesentliche Einschränkung","h2":"Auch für anspruchsvolle Architektur geeignet","lead":"Anders als bei Modulhäusern lassen sich als Elementhaus auch anspruchsvolle Architektur und großzügige Raumhöhen realisieren — einschließlich Mehrfamilienhäuser.","cards":[{"title":"Kranmontage","desc":"Aufstellung der Elemente und Dacharbeiten."},{"title":"Öffnungen","desc":"Montage von Fenstern, Terrassen-, Außen- und Innentüren."},{"title":"Ausbau","desc":"Böden, Zwischen- und Dachdecken, Leisten, Fliesen- und Malerarbeiten."},{"title":"Terrasse & Schornstein","desc":"Terrassenmontage sowie Schiedel-Metall- und Modulschornsteine."}]},"materials":{"eyebrow":"Materialauswahl","h2":"Auswahlmöglichkeiten (Standardlösungen im Katalog gesondert markiert)","cards":[{"title":"Außenverkleidung","desc":"Verschalung 21×145 mm oder 21×190 mm, polnische Schalung, unbesäumtes Brett, Fassadenplatte."},{"title":"Fenster & Türen","desc":"Dreifachverglaste Fenster (verschiedene Öffnungsarten), energieeffiziente Außentür, MDF-Innentüren."},{"title":"Dacheindeckung","desc":"Stein-, Blech-, SBS- und Bitumendach sowie Schalungs- und Grasdach."},{"title":"Bodenbelag","desc":"Eichenparkett (1- oder 3-Stab), Eichendielen oder Kiefern-Fußboden."},{"title":"Treppen","desc":"Kiefern- oder Eichenstufen, lackiert oder unbehandelt, mit Holz- oder Glasgeländer."},{"title":"Terrasse","desc":"Genutete Terrassendielen 28×120 mm oder 28×145 mm, braun oder grün imprägniert."}]},"callout":{"label":"Luft- und Winddichtheit:","text":"EstNor setzt Produkte des Branchenführers SIGA ein — Dampf- und Windsperrbahnen, Klebebänder und Dichtstoffe. Die Häuser werden nach SINTEF-Baunormen gefertigt; auf dem norwegischen Markt gelten TEK 10, bei Passivhäusern TEK 15."},"cta":{"h2":"Planen Sie ein großes oder anspruchsvolles Bauvorhaben?","body":"Das Elementhaus könnte die richtige Wahl sein — sprechen Sie mit uns über Ihr Projekt.","button":"Kontakt aufnehmen"}}') ON DUPLICATE KEY UPDATE content = VALUES(content);
INSERT INTO i18n_strings (lang_code, section, content) VALUES ('sv', 'page:houses-element-houses', '{"meta":{"title":"Elementhus | EstNor","desc":"EstNor OÜ tillverkar trästomme-elementhus vid elementhusfabriken i Kiili — ytter-, inner-, bjälklags-, tak- och terrasselement."},"hero":{"crumb":"Startsida","parent_label":"Hus","label":"Elementhus","eyebrow":"Fabrikstillverkat","h1":"Mer om elementhus","lead":"EstNor OÜ tillverkar trästomme-elementhus vid elementhusfabriken i Kiili. Där tillverkas ytter-, inner-, bjälklags-, tak- och terrasselement."},"benefits":{"h2":"Fördelar med elementhus","items":["Fabrikstillverkade hus håller hög kvalitet — bygget sker inomhus, i en kontrollerad miljö, utan väderskador (regn, snö, vind, temperatur)","Snabbt byggande — elementmontering sker vid specialbord utrustade med nödvändiga verktyg","Exakta ritningar gör tillverkningen snabb och effektiv — elementen tillverkas med millimeterprecision","Ingenjörer utför hållfasthetsberäkningar enligt lokala normer","Så mycket som möjligt färdigställs i fabriken: isolering, ång- och vindspärr, målad ytterpanel, fönster, dörrar","På plats monteras elementen med kran på 1–5 dagar beroende på husets storlek"]},"capabilities":{"eyebrow":"Utan större begränsningar","h2":"Passar även komplex arkitektur","lead":"Till skillnad från modulhus kan elementhus byggas med komplex arkitektur och stora rumshöjder — även flerbostadshus.","cards":[{"title":"Kranmontage","desc":"Resning av element och takarbeten."},{"title":"Öppningar","desc":"Montering av fönster, terrass-, ytter- och innerdörrar."},{"title":"Invändig färdigställning","desc":"Golv, bjälklag och tak, lister, kakel- och målningsarbeten."},{"title":"Terrass & skorsten","desc":"Terrassmontage samt Schiedel metall- och modulskorstenar."}]},"materials":{"eyebrow":"Materialval","h2":"Valmöjligheter","cards":[{"title":"Ytterpanel","desc":"Locklistpanel 21×145 mm eller 21×190 mm, polsk panel, okantad bräda, fasadskiva."},{"title":"Fönster & dörrar","desc":"Treglasfönster (olika öppningstyper), energieffektiv ytterdörr, MDF-innerdörrar."},{"title":"Yttertak","desc":"Tegel-, plåt-, SBS- och bitumentak samt panel- och grästak."},{"title":"Golv","desc":"Ekparkett (1- eller 3-stav), ekplank eller furugolv."},{"title":"Trappor","desc":"Furu- eller eksteg, lackerade eller obehandlade, med trä- eller glasräcke."},{"title":"Terrass","desc":"Räfflad terrassbräda 28×120 mm eller 28×145 mm, brun eller grön impregnering."}]},"callout":{"label":"Luft- och vindtäthet:","text":"EstNor använder produkter från branschledande SIGA — ång- och vindspärrsdukar, tejper och tätningsmedel. Husen tillverkas enligt SINTEF-byggnormer; på den norska marknaden enligt TEK 10, för passivhus TEK 15."},"cta":{"h2":"Planerar du ett stort eller komplext byggprojekt?","body":"Elementhus kan vara rätt val — berätta om ditt projekt för oss.","button":"Kontakta oss"}}') ON DUPLICATE KEY UPDATE content = VALUES(content);
INSERT INTO i18n_strings (lang_code, section, content) VALUES ('nb', 'page:houses-element-houses', '{"meta":{"title":"Elementhus | EstNor","desc":"EstNor OÜ produserer trerammede elementhus ved elementhusfabrikken i Kiili — yttervegg-, innervegg-, dekke-, tak- og terrasseelementer."},"hero":{"crumb":"Forsiden","parent_label":"Hus","label":"Elementhus","eyebrow":"Fabrikkbygget","h1":"Nærmere om elementhus","lead":"EstNor OÜ produserer trerammede elementhus ved elementhusfabrikken i Kiili. Der lages yttervegg-, innervegg-, dekke-, tak- og terrasseelementer."},"benefits":{"h2":"Fordeler med elementhus","items":["Fabrikkbygde hus holder høy kvalitet — bygging skjer innendørs, i et kontrollert miljø, uten værskader (regn, snø, vind, temperatur)","Rask bygging — elementmontering skjer på spesialbenker utstyrt med nødvendig verktøy","Presise arbeidstegninger gjør produksjonen rask og effektiv — elementene lages millimeternøyaktig","Ingeniører utfører styrkeberegninger etter lokale normer","Så mye som mulig ferdigstilles i fabrikken: isolasjon, damp- og vindsperre, malt kledning, vinduer, dører","På byggeplassen monteres elementene med kran på 1–5 dager avhengig av husets størrelse"]},"capabilities":{"eyebrow":"Uten vesentlige begrensninger","h2":"Passer også for krevende arkitektur","lead":"I motsetning til modulhus kan elementhus bygges med krevende arkitektur og store romhøyder — også leilighetsbygg.","cards":[{"title":"Kranmontasje","desc":"Oppføring av elementer og takarbeid."},{"title":"Åpninger","desc":"Montering av vinduer, terrasse-, ytter- og innerdører."},{"title":"Innvendig ferdigstillelse","desc":"Gulv, mellom- og takdekker, lister, flis- og malerarbeid."},{"title":"Terrasse & pipe","desc":"Terrassemontasje samt Schiedel metall- og modulpiper."}]},"materials":{"eyebrow":"Materialvalg","h2":"Valgmuligheter","cards":[{"title":"Yttervegg","desc":"Kledning 21×145 mm eller 21×190 mm, polsk kledning, ukantet bord, fasadeplate."},{"title":"Vinduer & dører","desc":"Trelagsvinduer (ulike åpningstyper), energieffektiv ytterdør, MDF-innerdører."},{"title":"Taktekking","desc":"Stein-, plate-, SBS- og bitumentak samt bord- og grastak."},{"title":"Gulv","desc":"Eikeparkett (1- eller 3-stav), eikeplank eller furugulv."},{"title":"Trapper","desc":"Furu- eller eiketrinn, lakkert eller ubehandlet, med tre- eller glassrekkverk."},{"title":"Terrasse","desc":"Rillet terrassebord 28×120 mm eller 28×145 mm, brun eller grønn impregnering."}]},"callout":{"label":"Luft- og vindtetthet:","text":"EstNor bruker produkter fra bransjeledende SIGA — damp- og vindsperreduker, tape og tetningsmidler. Husene produseres etter SINTEF-byggenormer; på det norske markedet gjelder TEK 10, for passivhus TEK 15."},"cta":{"h2":"Planlegger du et stort eller krevende byggeprosjekt?","body":"Elementhus kan være riktig valg — fortell oss om prosjektet ditt.","button":"Kontakt oss"}}') ON DUPLICATE KEY UPDATE content = VALUES(content);
INSERT INTO i18n_strings (lang_code, section, content) VALUES ('en', 'page:houses-element-houses', '{"meta":{"title":"Element Houses — EstNor","desc":"EstNor\'s factory-built element houses: exterior, interior, ceiling, roof and terrace elements built indoors to millimetre accuracy."},"hero":{"crumb":"Home","parent_label":"Houses","label":"Element Houses","eyebrow":"Factory built","h1":"The element house, in detail","lead":"EstNor OÜ builds timber-frame element houses at its element house factory in Kiili. The factory produces exterior, interior, ceiling, roof and terrace elements."},"benefits":{"h2":"Advantages of an element house","items":["A factory-built house is high quality — construction happens indoors, in a controlled environment, with no weather damage (rain, snow, wind, temperature)","Fast to build — elements are assembled at dedicated workbenches equipped with the necessary tools","Precise working drawings make production fast and efficient — elements come out to millimetre accuracy","Engineers carry out structural calculations to local standards, which rules out under-dimensioning","As much as possible is finished at the factory: insulation, vapour and wind barriers, painted exterior cladding, windows, doors","On site, elements are installed by crane in 1–5 days depending on the size of the house"]},"capabilities":{"eyebrow":"With no real restriction","h2":"Also suited to demanding architecture","lead":"Unlike modular houses, an element house can be built with complex architecture and generous ceiling heights — including apartment buildings.","cards":[{"title":"Crane installation","desc":"Erecting the elements and roof work."},{"title":"Openings","desc":"Fitting windows, terrace, exterior and interior doors."},{"title":"Finishing","desc":"Floors, intermediate and roof ceilings, mouldings, tiling and painting."},{"title":"Terrace & chimney","desc":"Terrace installation, plus Schiedel metal and modular chimneys."}]},"materials":{"eyebrow":"Choice of materials","h2":"Options available (standard solutions marked in bold elsewhere in the catalogue)","cards":[{"title":"Exterior cladding","desc":"21×145 mm or 21×190 mm cladding boards, Polish siding, unedged board, facade panel."},{"title":"Windows & doors","desc":"Triple-glazed windows (various opening types), energy-efficient exterior door, MDF interior doors."},{"title":"Roofing","desc":"Tile, sheet metal, SBS and bitumen roofing, as well as board and sod roofs."},{"title":"Flooring","desc":"Oak parquet (1- or 3-strip), oak plank or pine flooring."},{"title":"Stairs","desc":"Pine or oak treads, finished or unfinished, with wood or glass railings."},{"title":"Terrace","desc":"28×120 mm or 28×145 mm grooved decking boards, brown or green impregnation."}]},"callout":{"label":"Air- and wind-tightness:","text":"EstNor uses products from industry leader SIGA — vapour and wind barrier membranes, tapes and sealants. Houses are manufactured to SINTEF building standards; TEK 10 applies in the Norwegian market, TEK 15 for passive houses."},"cta":{"h2":"Planning a large or complex build?","body":"An element house could be the right choice — talk to us about your project.","button":"Contact EstNor"}}') ON DUPLICATE KEY UPDATE content = VALUES(content);
INSERT INTO i18n_strings (lang_code, section, content) VALUES ('et', 'page:houses-modular-houses', '{"meta":{"title":"Moodulmaja | EstNor","desc":"EstNori moodulmajad toodetakse tehases, ilmastikukindlas ja kontrollitud keskkonnas."},"hero":{"crumb":"Avaleht","parent_label":"Majad","label":"Moodulmaja","eyebrow":"Moodul","h1":"Moodulmajast lähemalt","lead":"EstNori moodulmajad toodetakse tehases, ilmastikukindlas ja kontrollitud keskkonnas — moodulid jõuavad objektile juba viimistletult."},"how":{"eyebrow":"Kuidas see töötab","h2":"Kuidas moodul valmib","paragraphs":["Moodulid koosnevad põranda-, seina- ja katuseelementidest, mis pannakse tehases kokku. Moodulid on seest ja väljast viimistletud ning katusekate on paigaldatud.","Kõik avatäited — aknad ja uksed — on paigaldatud ning seest ja väljast viimistletud (paled, liistud, veeplekid). Tehases teostatakse ka kõik eritööd: elektri-, toru-, ventilatsiooni- ja küttetööd. Vajadusel paigaldatakse moodulitesse ka sanitaartehnika ja mööbel."]},"suitable":{"eyebrow":"Valmis juba tehases","h2":"Mis on moodulis tehtud, enne kui see objektile jõuab","cards":[{"title":"Kandekonstruktsioon","desc":"Põranda-, seina- ja katuseelemendid tehases kokku monteeritud."},{"title":"Viimistlus","desc":"Seest ja väljast viimistletud, katusekate paigaldatud."},{"title":"Aknad ja uksed","desc":"Kõik avatäited paigaldatud ja viimistletud (paled, liistud, veeplekid)."},{"title":"Eritööd","desc":"Elektri-, toru-, ventilatsiooni- ja küttetööd tehases teostatud."}]},"pattern":{"eyebrow":"Avatud ehitussüsteem","h2":"Panus 369 Pattern Buildings programmi","body_pre":"EstNor panustab ","bold":"369 Pattern Buildings","body_post":" programmi — avatud lähtekoodiga, massikohandatavasse tööstuslikku ehitussüsteemi puitehitistele — aidates moodulehitusel liikuda targemate ja jätkusuutlikumate vaikeväärtuste suunas.","cta":"Vaata moodulprojekte"},"cta":{"h2":"Kas sul on moodulmaja projekt?","body":"Ühest suvilast kuni kortermajani — räägime läbi võimalused.","button":"Võta ühendust"}}') ON DUPLICATE KEY UPDATE content = VALUES(content);
INSERT INTO i18n_strings (lang_code, section, content) VALUES ('de', 'page:houses-modular-houses', '{"meta":{"title":"Modulhaus | EstNor","desc":"EstNor-Modulhäuser werden im Werk gefertigt, in einer witterungsunabhängigen und kontrollierten Umgebung."},"hero":{"crumb":"Startseite","parent_label":"Häuser","label":"Modulhaus","eyebrow":"Modular","h1":"Das Modulhaus im Detail","lead":"EstNor-Modulhäuser werden im Werk gefertigt, in einer witterungsunabhängigen und kontrollierten Umgebung — die Module kommen bereits ausgestattet auf der Baustelle an."},"how":{"eyebrow":"So funktioniert es","h2":"Wie ein Modul entsteht","paragraphs":["Module bestehen aus Boden-, Wand- und Dachelementen, die im Werk zusammengebaut werden. Module sind innen und außen ausgestattet, die Dacheindeckung ist montiert.","Alle Öffnungen — Fenster und Türen — sind eingebaut sowie innen und außen fertig verkleidet (Laibungen, Leisten, Wasserbleche). Im Werk werden auch alle Sonderarbeiten ausgeführt: Elektro-, Sanitär-, Lüftungs- und Heizungsinstallation. Bei Bedarf werden Sanitärtechnik und Möbel bereits in die Module eingebaut."]},"suitable":{"eyebrow":"Bereits im Werk erledigt","h2":"Was am Modul fertig ist, bevor es die Baustelle erreicht","cards":[{"title":"Tragkonstruktion","desc":"Boden-, Wand- und Dachelemente im Werk zusammengefügt."},{"title":"Ausbau","desc":"Innen und außen ausgestattet, Dacheindeckung montiert."},{"title":"Fenster & Türen","desc":"Alle Öffnungen eingebaut und fertig verkleidet (Laibungen, Leisten, Bleche)."},{"title":"Sonderarbeiten","desc":"Elektro-, Sanitär-, Lüftungs- und Heizungsinstallation bereits im Werk erledigt."}]},"pattern":{"eyebrow":"Offenes Bausystem","h2":"Beitrag zu 369 Pattern Buildings","body_pre":"EstNor beteiligt sich an ","bold":"369 Pattern Buildings","body_post":" — einem offenen, massenindividualisierbaren industriellen Bausystem für Holzgebäude — und hilft so, den modularen Bau hin zu intelligenteren, nachhaltigeren Standards zu bewegen.","cta":"Modulprojekte ansehen"},"cta":{"h2":"Haben Sie ein Modulhaus-Projekt?","body":"Von einem einzelnen Ferienhaus bis zum Mehrfamilienhaus — sprechen wir über die Möglichkeiten.","button":"Kontakt aufnehmen"}}') ON DUPLICATE KEY UPDATE content = VALUES(content);
INSERT INTO i18n_strings (lang_code, section, content) VALUES ('sv', 'page:houses-modular-houses', '{"meta":{"title":"Modulhus | EstNor","desc":"EstNors modulhus tillverkas i fabriken, i en väderoberoende och kontrollerad miljö."},"hero":{"crumb":"Startsida","parent_label":"Hus","label":"Modulhus","eyebrow":"Modulärt","h1":"Mer om modulhus","lead":"EstNors modulhus tillverkas i fabriken, i en väderoberoende och kontrollerad miljö — modulerna anländer redan färdigställda till byggplatsen."},"how":{"eyebrow":"Så fungerar det","h2":"Så tillverkas en modul","paragraphs":["Modulerna består av golv-, vägg- och takelement som monteras samman i fabriken. Modulerna är färdigställda in- och utvändigt, och taktäckningen är monterad.","Alla öppningar — fönster och dörrar — är monterade och färdigställda in- och utvändigt (foder, lister, plåtar). I fabriken utförs även alla specialarbeten: el, VVS, ventilation och värme. Vid behov installeras sanitet och möbler direkt i modulerna."]},"suitable":{"eyebrow":"Redan klart i fabriken","h2":"Vad som är klart innan modulen når byggplatsen","cards":[{"title":"Bärande stomme","desc":"Golv-, vägg- och takelement sammanfogade i fabriken."},{"title":"Färdigställning","desc":"In- och utvändigt färdigställt, taktäckning monterad."},{"title":"Fönster & dörrar","desc":"Alla öppningar monterade och färdigställda (foder, lister, plåtar)."},{"title":"Specialarbeten","desc":"El-, VVS-, ventilations- och värmeinstallationer klara i fabriken."}]},"pattern":{"eyebrow":"Öppet byggsystem","h2":"Bidrag till 369 Pattern Buildings","body_pre":"EstNor bidrar till ","bold":"369 Pattern Buildings","body_post":" — ett öppet, massanpassningsbart industriellt byggsystem för trähus — och hjälper till att driva modulbyggande mot smartare, mer hållbara standarder.","cta":"Se modulprojekt"},"cta":{"h2":"Har du ett modulhusprojekt?","body":"Från ett enskilt fritidshus till ett flerbostadshus — låt oss diskutera möjligheterna.","button":"Kontakta oss"}}') ON DUPLICATE KEY UPDATE content = VALUES(content);
INSERT INTO i18n_strings (lang_code, section, content) VALUES ('nb', 'page:houses-modular-houses', '{"meta":{"title":"Modulhus | EstNor","desc":"EstNors modulhus produseres i fabrikken, i et værbestandig og kontrollert miljø."},"hero":{"crumb":"Forsiden","parent_label":"Hus","label":"Modulhus","eyebrow":"Modulært","h1":"Nærmere om modulhus","lead":"EstNors modulhus produseres i fabrikken, i et værbestandig og kontrollert miljø — modulene ankommer byggeplassen allerede ferdigstilt."},"how":{"eyebrow":"Slik fungerer det","h2":"Slik lages en modul","paragraphs":["Modulene består av gulv-, vegg- og takelementer som settes sammen i fabrikken. Modulene er ferdigstilt innvendig og utvendig, og taktekkingen er montert.","Alle åpninger — vinduer og dører — er montert og ferdigstilt innvendig og utvendig (lister, beslag). I fabrikken utføres også alt spesialarbeid: elektrisk, rør, ventilasjon og oppvarming. Ved behov installeres sanitærutstyr og møbler direkte i modulene."]},"suitable":{"eyebrow":"Allerede klart i fabrikken","h2":"Hva som er ferdig før modulen når byggeplassen","cards":[{"title":"Bærende konstruksjon","desc":"Gulv-, vegg- og takelementer satt sammen i fabrikken."},{"title":"Ferdigstillelse","desc":"Innvendig og utvendig ferdigstilt, taktekking montert."},{"title":"Vinduer & dører","desc":"Alle åpninger montert og ferdigstilt (lister, beslag)."},{"title":"Spesialarbeid","desc":"Elektrisk, rør, ventilasjon og oppvarming ferdig i fabrikken."}]},"pattern":{"eyebrow":"Åpent byggesystem","h2":"Bidrag til 369 Pattern Buildings","body_pre":"EstNor bidrar til ","bold":"369 Pattern Buildings","body_post":" — et åpent, masse-tilpasningsbart industrielt byggesystem for trebygninger — og bidrar til å flytte modulbygging mot smartere, mer bærekraftige standarder.","cta":"Se modulprosjekter"},"cta":{"h2":"Har du et modulhusprosjekt?","body":"Fra én enkelt hytte til et leilighetsbygg — la oss diskutere mulighetene.","button":"Kontakt oss"}}') ON DUPLICATE KEY UPDATE content = VALUES(content);
INSERT INTO i18n_strings (lang_code, section, content) VALUES ('en', 'page:houses-modular-houses', '{"meta":{"title":"Modular Houses — EstNor","desc":"EstNor\'s factory-finished modular houses for private homes, townhouses, apartment and public buildings."},"hero":{"crumb":"Home","parent_label":"Houses","label":"Modular Houses","eyebrow":"Modular","h1":"Modules finished in the factory, joined on site","lead":"More than 90% of the work happens indoors, in a weatherproof, controlled environment — modules arrive on site already finished inside and out."},"how":{"eyebrow":"How it works","h2":"An innovative, flexible construction system","paragraphs":["EstNor modular buildings offer an innovative, flexible approach and the best possible construction outcome. Each module consists of floor, wall and roof elements assembled together in the factory, finished inside and out, with roofing installed.","All window and door openings are fitted and finished before the module leaves the factory. We also carry out all special work — electrical, plumbing, ventilation and heating — while the module is still indoors."]},"suitable":{"eyebrow":"Suitable for","h2":"Where modular construction fits","cards":[{"title":"Private houses","desc":"Single-family homes delivered largely complete from the factory."},{"title":"Cottages","desc":"Compact, efficient modules for holiday and countryside living."},{"title":"Townhouses","desc":"Modules joined side-by-side for row-house developments."},{"title":"Apartment & public buildings","desc":"Stacked and joined modules forming full multi-storey buildings."}]},"pattern":{"eyebrow":"Open building system","h2":"Contributing to 369 Pattern Buildings","body_pre":"EstNor contributes to ","bold":"369 Pattern Buildings","body_post":" — an open-source, mass-customisable industrial building system for wooden buildings — helping push modular construction toward smarter, more sustainable defaults.","cta":"See modular projects"},"cta":{"h2":"Have a modular project in mind?","body":"From a single cottage to a full apartment building, let\'s talk through the options.","button":"Contact EstNor"}}') ON DUPLICATE KEY UPDATE content = VALUES(content);
INSERT INTO i18n_strings (lang_code, section, content) VALUES ('et', 'page:houses', '{"meta":{"title":"Majad | EstNor","desc":"EstNor toodab elementmaju ja moodulmaju Kiili tehases."},"hero":{"crumb":"Avaleht","eyebrow":"Kaks ehitusviisi, üks tehase standard","h1":"Vali, kuidas su maja valmib","lead":"Iga EstNori maja saab alguse tehasest. Vali ehitusviis, mis sobib sinu projekti, arhitektuuri, ajakava ja eelarvega.","label":"Majad"},"element":{"tag":"Tehases toodetud","title":"Elementmajad","desc":"Seinad, katus ja põrand toodetakse tehases ning pannakse objektil kokku — ilma suuremate piiranguteta suuruse ega arhitektuuri osas.","cta":"Loe lähemalt"},"modular":{"tag":"Moodul","title":"Moodulmajad","desc":"Täielikult viimistletud moodulid — elekter, torustik ja küte kaasa arvatud — mis pannakse objektil kokku valmis majaks.","cta":"Loe lähemalt"},"compare":{"eyebrow":"Kumb sobib sulle?","h2":"Kahe ehitusviisi võrdlus","cards":[{"title":"Elementmajad","desc":"Sobivad suurtele või arhitektuuriliselt keerukatele hoonetele ja kortermajadele. Tehases toodetud seinad, katus ja terrass pannakse objektil kokku."},{"title":"Moodulmajad","desc":"Sobivad kiire graafikuga projektidele — üle 90% tööst on tehtud juba tehases, enne kui moodul objektile jõuab."}]},"renovate":{"eyebrow":"Olemasolev hoone?","h2":"EstNor ka renoveerib, mitte ainult ei ehita uut","lead":"Sama tehasetäpsus kehtib ka tehaselise renoveerimise puhul: fassaadielemendid, mis tõstavad kortermaja energiatõhusust vaid mõne nädalaga.","cta":"Mis on tehaseline renoveerimine?"}}') ON DUPLICATE KEY UPDATE content = VALUES(content);
INSERT INTO i18n_strings (lang_code, section, content) VALUES ('en', 'page:houses', '{"meta":{"title":"Houses — EstNor","desc":"EstNor builds element houses and modular houses at our factory in Kiili, Estonia."},"hero":{"crumb":"Home","eyebrow":"Two build methods, one factory standard","h1":"Choose how your house is built","lead":"Every EstNor house begins indoors. Choose the build method that fits your project — architecture, timeline and budget all play a part.","label":"Houses"},"element":{"tag":"Factory built","title":"Element Houses","desc":"Walls, roofs and floors built indoors, then assembled on site — with no real limit on size or architectural complexity.","cta":"Learn more"},"modular":{"tag":"Modular","title":"Modular Houses","desc":"Fully finished modules — including electrics, plumbing and heating — joined together on site into the finished building.","cta":"Learn more"},"compare":{"eyebrow":"Which method is right for you?","h2":"Comparing the two build methods","cards":[{"title":"Element Houses","desc":"Best for: large or architecturally complex homes and apartment buildings. Indoor-built walls, roofs and terraces assembled on site."},{"title":"Modular Houses","desc":"Best for: fast-track projects — private houses, townhouses, apartment and public buildings — with >90% of work done in-factory."}]},"renovate":{"eyebrow":"Already have a building?","h2":"EstNor also renovates, not just builds new","lead":"The same factory precision applies to serial renovation: prefabricated facade elements that upgrade an existing apartment building in weeks.","cta":"What is serial renovation?"}}') ON DUPLICATE KEY UPDATE content = VALUES(content);
INSERT INTO i18n_strings (lang_code, section, content) VALUES ('de', 'page:houses', '{"meta":{"title":"Häuser | EstNor","desc":"EstNor fertigt Elementhäuser und Modulhäuser im Werk in Kiili, Estland."},"hero":{"crumb":"Startseite","eyebrow":"Zwei Bauweisen, ein Werksstandard","h1":"Wählen Sie, wie Ihr Haus gebaut wird","lead":"Jedes EstNor-Haus beginnt im Werk. Wählen Sie die Bauweise, die zu Architektur, Zeitplan und Budget Ihres Projekts passt.","label":"Häuser"},"element":{"tag":"Werksgefertigt","title":"Elementhäuser","desc":"Wände, Dach und Boden werden im Werk gefertigt und vor Ort montiert — ohne wesentliche Einschränkung bei Größe oder Architektur.","cta":"Mehr erfahren"},"modular":{"tag":"Modular","title":"Modulhäuser","desc":"Vollständig ausgestattete Module — inklusive Elektrik, Sanitär und Heizung — die vor Ort zum fertigen Haus zusammengefügt werden.","cta":"Mehr erfahren"},"compare":{"eyebrow":"Welche Bauweise passt zu Ihnen?","h2":"Die beiden Bauweisen im Vergleich","cards":[{"title":"Elementhäuser","desc":"Geeignet für große oder architektonisch anspruchsvolle Gebäude und Mehrfamilienhäuser. Im Werk gefertigte Wände, Dach und Terrasse werden vor Ort montiert."},{"title":"Modulhäuser","desc":"Geeignet für Projekte mit engem Zeitplan — über 90 % der Arbeit ist bereits im Werk erledigt, bevor das Modul die Baustelle erreicht."}]},"renovate":{"eyebrow":"Bereits ein Gebäude vorhanden?","h2":"EstNor saniert auch, nicht nur Neubau","lead":"Dieselbe Werkspräzision gilt für die serielle Sanierung: Fassadenelemente, die ein Mehrfamilienhaus in wenigen Wochen energieeffizient machen.","cta":"Was ist serielle Sanierung?"}}') ON DUPLICATE KEY UPDATE content = VALUES(content);
INSERT INTO i18n_strings (lang_code, section, content) VALUES ('sv', 'page:houses', '{"meta":{"title":"Hus | EstNor","desc":"EstNor tillverkar elementhus och modulhus vid fabriken i Kiili, Estland."},"hero":{"crumb":"Startsida","eyebrow":"Två byggmetoder, en fabriksstandard","h1":"Välj hur ditt hus byggs","lead":"Varje EstNor-hus börjar i fabriken. Välj den byggmetod som passar projektets arkitektur, tidsplan och budget.","label":"Hus"},"element":{"tag":"Fabrikstillverkat","title":"Elementhus","desc":"Väggar, tak och golv tillverkas i fabriken och monteras på plats — utan större begränsningar för storlek eller arkitektur.","cta":"Läs mer"},"modular":{"tag":"Modulärt","title":"Modulhus","desc":"Helt färdigställda moduler — inklusive el, vatten och värme — som fogas samman på plats till ett färdigt hus.","cta":"Läs mer"},"compare":{"eyebrow":"Vilken metod passar dig?","h2":"Jämförelse av de två byggmetoderna","cards":[{"title":"Elementhus","desc":"Passar stora eller arkitektoniskt komplexa byggnader och flerbostadshus. Fabrikstillverkade väggar, tak och terrass monteras på plats."},{"title":"Modulhus","desc":"Passar projekt med snäv tidsplan — över 90 % av arbetet är redan gjort i fabriken innan modulen når byggplatsen."}]},"renovate":{"eyebrow":"Redan en befintlig byggnad?","h2":"EstNor renoverar också, inte bara nybygger","lead":"Samma fabriksprecision gäller för modernisering av flerbostadshus: fasadelement som höjer energieffektiviteten på bara några veckor.","cta":"Vad är modernisering av flerbostadshus?"}}') ON DUPLICATE KEY UPDATE content = VALUES(content);
INSERT INTO i18n_strings (lang_code, section, content) VALUES ('nb', 'page:houses', '{"meta":{"title":"Hus | EstNor","desc":"EstNor produserer elementhus og modulhus ved fabrikken i Kiili, Estland."},"hero":{"crumb":"Forsiden","eyebrow":"To byggemetoder, én fabrikkstandard","h1":"Velg hvordan huset ditt bygges","lead":"Hvert EstNor-hus starter i fabrikken. Velg byggemetoden som passer prosjektets arkitektur, tidsplan og budsjett.","label":"Hus"},"element":{"tag":"Fabrikkbygget","title":"Elementhus","desc":"Vegger, tak og gulv produseres i fabrikken og monteres på stedet — uten vesentlige begrensninger på størrelse eller arkitektur.","cta":"Les mer"},"modular":{"tag":"Modulært","title":"Modulhus","desc":"Fullstendig ferdigstilte moduler — inkludert elektrisk, rør og oppvarming — som settes sammen til et ferdig hus på stedet.","cta":"Les mer"},"compare":{"eyebrow":"Hvilken metode passer deg?","h2":"Sammenligning av de to byggemetodene","cards":[{"title":"Elementhus","desc":"Passer store eller arkitektonisk krevende bygg og leilighetsbygg. Fabrikkbygde vegger, tak og terrasse monteres på stedet."},{"title":"Modulhus","desc":"Passer prosjekter med stram tidsplan — over 90 % av arbeidet er allerede gjort i fabrikken før modulen når byggeplassen."}]},"renovate":{"eyebrow":"Har du allerede en bygning?","h2":"EstNor rehabiliterer også, ikke bare nybygg","lead":"Den samme fabrikkpresisjonen gjelder for modernisering av leilighetsbygg: fasadeelementer som gjør et leilighetsbygg energieffektivt på bare noen uker.","cta":"Hva er modernisering av leilighetsbygg?"}}') ON DUPLICATE KEY UPDATE content = VALUES(content);
INSERT INTO i18n_strings (lang_code, section, content) VALUES ('et', 'page:projects', '{"meta":{"title":"Projektid | EstNor","desc":"EstNori majaehitus- ja renoveerimisprojektid Eestis, Norras ja Rootsis."},"hero":{"crumb":"Avaleht","label":"Projektid","eyebrow":"Projektid","h1":"Uusehitised ja renoveerimised kõrvuti","lead":"Valik EstNori valminud ja pooleliolevaid maja- ning fassaadirenoveerimise projekte Eestis, Norras ja Rootsis."},"references_section":{"eyebrow":"Tehaseline renoveerimine","h2":"Renoveerimisreferentsid","projects":[{"svg":"<svg viewBox=\\"0 0 200 150\\" xmlns=\\"http://www.w3.org/2000/svg\\"><rect width=\\"200\\" height=\\"150\\" fill=\\"#e9efe7\\"/><g fill=\\"none\\" stroke=\\"#1f4d3a\\" stroke-width=\\"2\\"><rect x=\\"20\\" y=\\"20\\" width=\\"26\\" height=\\"28\\" rx=\\"2\\"/><rect x=\\"24\\" y=\\"25\\" width=\\"9\\" height=\\"18\\" fill=\\"#1f4d3a\\" opacity=\\".25\\"/><rect x=\\"52\\" y=\\"20\\" width=\\"26\\" height=\\"28\\" rx=\\"2\\"/><rect x=\\"56\\" y=\\"25\\" width=\\"9\\" height=\\"18\\" fill=\\"#1f4d3a\\" opacity=\\".25\\"/><rect x=\\"84\\" y=\\"20\\" width=\\"26\\" height=\\"28\\" rx=\\"2\\"/><rect x=\\"88\\" y=\\"25\\" width=\\"9\\" height=\\"18\\" fill=\\"#1f4d3a\\" opacity=\\".25\\"/><rect x=\\"20\\" y=\\"54\\" width=\\"26\\" height=\\"28\\" rx=\\"2\\"/><rect x=\\"24\\" y=\\"59\\" width=\\"9\\" height=\\"18\\" fill=\\"#1f4d3a\\" opacity=\\".25\\"/><rect x=\\"52\\" y=\\"54\\" width=\\"26\\" height=\\"28\\" rx=\\"2\\"/><rect x=\\"56\\" y=\\"59\\" width=\\"9\\" height=\\"18\\" fill=\\"#1f4d3a\\" opacity=\\".25\\"/><rect x=\\"84\\" y=\\"54\\" width=\\"26\\" height=\\"28\\" rx=\\"2\\"/><rect x=\\"88\\" y=\\"59\\" width=\\"9\\" height=\\"18\\" fill=\\"#1f4d3a\\" opacity=\\".25\\"/></g></svg>","meta":"Eesti · 2022–2027","title":"KredEx pilootprogramm tehaselise renoveerimise jaoks","tags":["Fassaadielemendid","Pilootprogramm","Elanikega majas"],"desc":"Riiklik pilootprogramm elamute tehaseliseks renoveerimiseks. EstNor oli esimene osalev elementide tootja ja tarnis programmis suurima mahu fassaadielemente.","stats":[{"value":"12","label":"kortermaja"},{"value":"1.","label":"osalev tootja"}],"addresses_label":"Renoveeritud hooned:","addresses":["Kooli 5, Sindi","Kotka 8, Tallinn","Muldvalge 1, Tallinn","Nisu 3, Tallinn","Pallasti 10, Tallinn","Pärnu mnt. 133, Tallinn","Riia 80, Pärnu","Turu 15, Tartu","Ojasoo 6, Kuressaare","Anne 2, Tartu","Lasteaia 2, Kehtna","Tule 4, Saue"]},{"svg":"<svg viewBox=\\"0 0 200 150\\" xmlns=\\"http://www.w3.org/2000/svg\\"><rect width=\\"200\\" height=\\"150\\" fill=\\"#e9efe7\\"/><path d=\\"M40 55 L100 25 L160 55 Z\\" fill=\\"#dd8a2c\\"/><rect x=\\"45\\" y=\\"55\\" width=\\"110\\" height=\\"80\\" fill=\\"none\\" stroke=\\"#1f4d3a\\" stroke-width=\\"2\\"/><g fill=\\"#1f4d3a\\" opacity=\\".25\\"><rect x=\\"58\\" y=\\"68\\" width=\\"18\\" height=\\"22\\"/><rect x=\\"91\\" y=\\"68\\" width=\\"18\\" height=\\"22\\"/><rect x=\\"124\\" y=\\"68\\" width=\\"18\\" height=\\"22\\"/><rect x=\\"58\\" y=\\"100\\" width=\\"18\\" height=\\"22\\"/><rect x=\\"124\\" y=\\"100\\" width=\\"18\\" height=\\"22\\"/></g><rect x=\\"91\\" y=\\"100\\" width=\\"18\\" height=\\"35\\" fill=\\"#1f4d3a\\" opacity=\\".4\\"/></svg>","meta":"Tallinn, Eesti","title":"Loodusmaja — keskkonnahoone Tallinnas","tags":["Fassaadi- ja katuseelemendid","Eelpaigaldatud aknad","Puitehitis"],"desc":"Ühele Eesti suurimale puithoonele tarnib EstNor ligikaudu 8000 m² eeltoodetud fassaadi- ja katuseelemente — kaasa arvatud tehases paigaldatud aknad.","stats":[{"value":"~8000 m²","label":"elementide pindala"},{"value":"Tehas","label":"akende paigaldus"}]},{"svg":"<svg viewBox=\\"0 0 200 150\\" xmlns=\\"http://www.w3.org/2000/svg\\"><rect width=\\"200\\" height=\\"150\\" fill=\\"#e9efe7\\"/><rect x=\\"45\\" y=\\"35\\" width=\\"110\\" height=\\"95\\" fill=\\"none\\" stroke=\\"#b96f1c\\" stroke-width=\\"2\\" stroke-dasharray=\\"7 6\\"/><text x=\\"100\\" y=\\"90\\" text-anchor=\\"middle\\" font-family=\\"Bricolage Grotesque, sans-serif\\" font-size=\\"15\\" fill=\\"#b96f1c\\">?</text></svg>","meta":"Ettevalmistamisel","title":"Esimesed projektid väljaspool Eestit","tags":["Otsib partnereid","Kortermaja","1950–1979"],"desc":"EstNor laiendab tootmisvõimsust ekspordituru jaoks ja otsib ehitus-, renoveerimis- ja elamuettevõtteid järgmiste tehaseliste fassaadiprojektide jaoks. Sinu projekt võiks olla siin."}]},"other_section":{"eyebrow":"Uusehitised","h2":"Muud projektid","cards":[{"tag":"Pärnu, Eesti","title":"Stroomi Rannahoone","desc":"Rannaäärne puithoone, ehitatud EstNori element- ja fassaaditehnoloogiaga."},{"tag":"Oslo, Norra","title":"Kortermaja Oslos","desc":"Mitmekorruseline kortermaja, ehitatud EstNori tehases valminud moodulitest."},{"tag":"Rootsi","title":"Elementmajast pere-elamu","desc":"Suur pereelamu, ehitatud tehases toodetud välis- ja siseelementidest."},{"tag":"Eesti","title":"Suvilate arendus","desc":"Kiilis toodetud moodulsuvilate kompleks, tarnitud valmis viimistletuna Eesti rannikualale."}]},"context_left":{"eyebrow":"Kontekst","h2":"Mida need projektid näitavad","p":"EstNori jaoks ei ole tehaseline fassaadirenoveerimine elanikega majas kuulutus, vaid käimasolev tootmine: standardsed elemendid, korduvad hoonetüübid, paigaldus mõne nädalaga. Järgmine samm on viia see tootmine koos kohalike partneritega uutele turgudele ja konkreetsetesse linnaosadesse."},"context_right":{"eyebrow":"Sinu projekt","h2":"Ole järgmine referents","p":"Kui plaanid tehaselist fassaadiprojekti ja otsid tootmispartnerit, räägime hoonetüüpidest, mahtudest ja ajakavast.","button":"Räägi meile oma projektist"},"cta":{"h2":"Kas sul on oma projekt?","body":"Räägi meile sellest ja soovitame sobiva EstNori ehitusviisi.","button":"Võta ühendust"}}') ON DUPLICATE KEY UPDATE content = VALUES(content);
INSERT INTO i18n_strings (lang_code, section, content) VALUES ('en', 'page:projects', '{"meta":{"title":"Projects — EstNor","desc":"A selection of EstNor timber house and facade-renovation projects across Estonia, Norway and Sweden."},"hero":{"crumb":"Home","label":"Projects","eyebrow":"Projects","h1":"New builds and renovations, side by side","lead":"A selection of the homes, buildings and facade-renovation projects EstNor has delivered or is preparing — across Estonia, Norway, Sweden and beyond."},"references_section":{"eyebrow":"Serial renovation","h2":"Renovation references","projects":[{"svg":"<svg viewBox=\\"0 0 200 150\\" xmlns=\\"http://www.w3.org/2000/svg\\"><rect width=\\"200\\" height=\\"150\\" fill=\\"#e9efe7\\"/><g fill=\\"none\\" stroke=\\"#1f4d3a\\" stroke-width=\\"2\\"><rect x=\\"20\\" y=\\"20\\" width=\\"26\\" height=\\"28\\" rx=\\"2\\"/><rect x=\\"24\\" y=\\"25\\" width=\\"9\\" height=\\"18\\" fill=\\"#1f4d3a\\" opacity=\\".25\\"/><rect x=\\"52\\" y=\\"20\\" width=\\"26\\" height=\\"28\\" rx=\\"2\\"/><rect x=\\"56\\" y=\\"25\\" width=\\"9\\" height=\\"18\\" fill=\\"#1f4d3a\\" opacity=\\".25\\"/><rect x=\\"84\\" y=\\"20\\" width=\\"26\\" height=\\"28\\" rx=\\"2\\"/><rect x=\\"88\\" y=\\"25\\" width=\\"9\\" height=\\"18\\" fill=\\"#1f4d3a\\" opacity=\\".25\\"/><rect x=\\"20\\" y=\\"54\\" width=\\"26\\" height=\\"28\\" rx=\\"2\\"/><rect x=\\"24\\" y=\\"59\\" width=\\"9\\" height=\\"18\\" fill=\\"#1f4d3a\\" opacity=\\".25\\"/><rect x=\\"52\\" y=\\"54\\" width=\\"26\\" height=\\"28\\" rx=\\"2\\"/><rect x=\\"56\\" y=\\"59\\" width=\\"9\\" height=\\"18\\" fill=\\"#1f4d3a\\" opacity=\\".25\\"/><rect x=\\"84\\" y=\\"54\\" width=\\"26\\" height=\\"28\\" rx=\\"2\\"/><rect x=\\"88\\" y=\\"59\\" width=\\"9\\" height=\\"18\\" fill=\\"#1f4d3a\\" opacity=\\".25\\"/></g></svg>","meta":"Estonia · 2022–2027","title":"KredEx pilot programme for serial renovation","tags":["Facade elements","Pilot programme","While occupied"],"desc":"State pilot programme for the factory-based renovation of residential buildings. EstNor was the first participating element manufacturer and supplied the largest volume of facade elements in the programme.","stats":[{"value":"12","label":"apartment buildings"},{"value":"1st","label":"participating manufacturer"}],"addresses_label":"Renovated buildings:","addresses":["Kooli 5, Sindi","Kotka 8, Tallinn","Muldvalge 1, Tallinn","Nisu 3, Tallinn","Pallasti 10, Tallinn","Pärnu mnt. 133, Tallinn","Riia 80, Pärnu","Turu 15, Tartu","Ojasoo 6, Kuressaare","Anne 2, Tartu","Lasteaia 2, Kehtna","Tule 4, Saue"]},{"svg":"<svg viewBox=\\"0 0 200 150\\" xmlns=\\"http://www.w3.org/2000/svg\\"><rect width=\\"200\\" height=\\"150\\" fill=\\"#e9efe7\\"/><path d=\\"M40 55 L100 25 L160 55 Z\\" fill=\\"#dd8a2c\\"/><rect x=\\"45\\" y=\\"55\\" width=\\"110\\" height=\\"80\\" fill=\\"none\\" stroke=\\"#1f4d3a\\" stroke-width=\\"2\\"/><g fill=\\"#1f4d3a\\" opacity=\\".25\\"><rect x=\\"58\\" y=\\"68\\" width=\\"18\\" height=\\"22\\"/><rect x=\\"91\\" y=\\"68\\" width=\\"18\\" height=\\"22\\"/><rect x=\\"124\\" y=\\"68\\" width=\\"18\\" height=\\"22\\"/><rect x=\\"58\\" y=\\"100\\" width=\\"18\\" height=\\"22\\"/><rect x=\\"124\\" y=\\"100\\" width=\\"18\\" height=\\"22\\"/></g><rect x=\\"91\\" y=\\"100\\" width=\\"18\\" height=\\"35\\" fill=\\"#1f4d3a\\" opacity=\\".4\\"/></svg>","meta":"Tallinn, Estonia","title":"Loodusmaja — environmental building, Tallinn","tags":["Facade & roof elements","Pre-installed windows","Timber construction"],"desc":"For one of the largest timber buildings in Estonia, EstNor supplies around 8,000 m² of prefabricated facade and roof elements — including factory-installed windows.","stats":[{"value":"≈8,000 m²","label":"element area"},{"value":"Factory","label":"window installation"}]},{"svg":"<svg viewBox=\\"0 0 200 150\\" xmlns=\\"http://www.w3.org/2000/svg\\"><rect width=\\"200\\" height=\\"150\\" fill=\\"#e9efe7\\"/><rect x=\\"45\\" y=\\"35\\" width=\\"110\\" height=\\"95\\" fill=\\"none\\" stroke=\\"#b96f1c\\" stroke-width=\\"2\\" stroke-dasharray=\\"7 6\\"/><text x=\\"100\\" y=\\"90\\" text-anchor=\\"middle\\" font-family=\\"Bricolage Grotesque, sans-serif\\" font-size=\\"15\\" fill=\\"#b96f1c\\">?</text></svg>","meta":"In preparation","title":"First projects beyond Estonia","tags":["Seeking partners","Apartment building","1950–1979"],"desc":"EstNor is expanding its production capacity for export markets and is looking for construction, renovation and housing companies for the next serial facade projects. Your project could be shown here."}]},"other_section":{"eyebrow":"New builds","h2":"Other projects","cards":[{"tag":"Pärnu, Estonia","title":"Stroomi Rannahoone","desc":"A seaside building in Pärnu, built using EstNor\'s element and facade technology."},{"tag":"Oslo, Norway","title":"Oslo apartment building","desc":"A multi-storey apartment building built from EstNor\'s factory-finished modules."},{"tag":"Sweden","title":"Element-built family home","desc":"A large family home built from factory-produced exterior and interior elements."},{"tag":"Estonia","title":"Cottage development","desc":"A cluster of modular cottages manufactured in Kiili, delivered fully finished to the Estonian coast."}]},"context_left":{"eyebrow":"Context","h2":"What these projects show","p":"For EstNor, serial facade renovation with tenants in place is not an announcement but ongoing production: standardised elements, recurring building types, installation in weeks. The task now is to transfer this production to new markets and concrete neighbourhoods together with local partners."},"context_right":{"eyebrow":"Your project","h2":"Be the next reference","p":"If you are planning a serial facade project and looking for a manufacturing partner, let\'s talk about building types, quantities and schedule.","button":"Discuss a project"},"cta":{"h2":"Have a project of your own?","body":"Tell us about it and we\'ll suggest the right EstNor build method.","button":"Contact EstNor"}}') ON DUPLICATE KEY UPDATE content = VALUES(content);
INSERT INTO i18n_strings (lang_code, section, content) VALUES ('de', 'page:projects', '{"meta":{"title":"Projekte | EstNor","desc":"EstNor-Bau- und Sanierungsprojekte in Estland, Norwegen und Schweden."},"hero":{"crumb":"Startseite","label":"Projekte","eyebrow":"Projekte","h1":"Neubau und Sanierung nebeneinander","lead":"Eine Auswahl der von EstNor errichteten Häuser, Gebäude und Fassadensanierungsprojekte in Estland, Norwegen, Schweden und darüber hinaus."},"references_section":{"eyebrow":"Serielle Sanierung","h2":"Referenzen zur seriellen Sanierung","projects":[{"svg":"<svg viewBox=\\"0 0 200 150\\" xmlns=\\"http://www.w3.org/2000/svg\\"><rect width=\\"200\\" height=\\"150\\" fill=\\"#e9efe7\\"/><g fill=\\"none\\" stroke=\\"#1f4d3a\\" stroke-width=\\"2\\"><rect x=\\"20\\" y=\\"20\\" width=\\"26\\" height=\\"28\\" rx=\\"2\\"/><rect x=\\"24\\" y=\\"25\\" width=\\"9\\" height=\\"18\\" fill=\\"#1f4d3a\\" opacity=\\".25\\"/><rect x=\\"52\\" y=\\"20\\" width=\\"26\\" height=\\"28\\" rx=\\"2\\"/><rect x=\\"56\\" y=\\"25\\" width=\\"9\\" height=\\"18\\" fill=\\"#1f4d3a\\" opacity=\\".25\\"/><rect x=\\"84\\" y=\\"20\\" width=\\"26\\" height=\\"28\\" rx=\\"2\\"/><rect x=\\"88\\" y=\\"25\\" width=\\"9\\" height=\\"18\\" fill=\\"#1f4d3a\\" opacity=\\".25\\"/><rect x=\\"20\\" y=\\"54\\" width=\\"26\\" height=\\"28\\" rx=\\"2\\"/><rect x=\\"24\\" y=\\"59\\" width=\\"9\\" height=\\"18\\" fill=\\"#1f4d3a\\" opacity=\\".25\\"/><rect x=\\"52\\" y=\\"54\\" width=\\"26\\" height=\\"28\\" rx=\\"2\\"/><rect x=\\"56\\" y=\\"59\\" width=\\"9\\" height=\\"18\\" fill=\\"#1f4d3a\\" opacity=\\".25\\"/><rect x=\\"84\\" y=\\"54\\" width=\\"26\\" height=\\"28\\" rx=\\"2\\"/><rect x=\\"88\\" y=\\"59\\" width=\\"9\\" height=\\"18\\" fill=\\"#1f4d3a\\" opacity=\\".25\\"/></g></svg>","meta":"Estland · 2022–2027","title":"KredEx-Pilotprogramm für serielle Sanierung","tags":["Fassadenelemente","Pilotprogramm","Im bewohnten Zustand"],"desc":"Staatliches Pilotprogramm zur werkseitigen Sanierung von Wohngebäuden. EstNor war der erste teilnehmende Elementhersteller und lieferte das größte Volumen an Fassadenelementen im Programm.","stats":[{"value":"12","label":"Mehrfamilienhäuser"},{"value":"1.","label":"teilnehmender Hersteller"}],"addresses_label":"Renovierte Gebäude:","addresses":["Kooli 5, Sindi","Kotka 8, Tallinn","Muldvalge 1, Tallinn","Nisu 3, Tallinn","Pallasti 10, Tallinn","Pärnu mnt. 133, Tallinn","Riia 80, Pärnu","Turu 15, Tartu","Ojasoo 6, Kuressaare","Anne 2, Tartu","Lasteaia 2, Kehtna","Tule 4, Saue"]},{"svg":"<svg viewBox=\\"0 0 200 150\\" xmlns=\\"http://www.w3.org/2000/svg\\"><rect width=\\"200\\" height=\\"150\\" fill=\\"#e9efe7\\"/><path d=\\"M40 55 L100 25 L160 55 Z\\" fill=\\"#dd8a2c\\"/><rect x=\\"45\\" y=\\"55\\" width=\\"110\\" height=\\"80\\" fill=\\"none\\" stroke=\\"#1f4d3a\\" stroke-width=\\"2\\"/><g fill=\\"#1f4d3a\\" opacity=\\".25\\"><rect x=\\"58\\" y=\\"68\\" width=\\"18\\" height=\\"22\\"/><rect x=\\"91\\" y=\\"68\\" width=\\"18\\" height=\\"22\\"/><rect x=\\"124\\" y=\\"68\\" width=\\"18\\" height=\\"22\\"/><rect x=\\"58\\" y=\\"100\\" width=\\"18\\" height=\\"22\\"/><rect x=\\"124\\" y=\\"100\\" width=\\"18\\" height=\\"22\\"/></g><rect x=\\"91\\" y=\\"100\\" width=\\"18\\" height=\\"35\\" fill=\\"#1f4d3a\\" opacity=\\".4\\"/></svg>","meta":"Tallinn, Estland","title":"Loodusmaja – Umwelthaus Tallinn","tags":["Fassaden- & Dachelemente","Vormontierte Fenster","Holzbau"],"desc":"Für eines der größten Holzgebäude Estlands liefert EstNor rund 8.000 m² vorgefertigte Fassaden- und Dachelemente – inklusive im Werk eingebauter Fenster.","stats":[{"value":"~8.000 m²","label":"Elementfläche"},{"value":"Werk","label":"Fenstereinbau"}]},{"svg":"<svg viewBox=\\"0 0 200 150\\" xmlns=\\"http://www.w3.org/2000/svg\\"><rect width=\\"200\\" height=\\"150\\" fill=\\"#e9efe7\\"/><rect x=\\"45\\" y=\\"35\\" width=\\"110\\" height=\\"95\\" fill=\\"none\\" stroke=\\"#b96f1c\\" stroke-width=\\"2\\" stroke-dasharray=\\"7 6\\"/><text x=\\"100\\" y=\\"90\\" text-anchor=\\"middle\\" font-family=\\"Bricolage Grotesque, sans-serif\\" font-size=\\"15\\" fill=\\"#b96f1c\\">?</text></svg>","meta":"Deutschland · in Vorbereitung","title":"Erste Projekte in Deutschland","tags":["Partnersuche","Mehrfamilienhaus","1950–1979"],"desc":"EstNor baut die Fertigungskapazität gezielt für den deutschen Markt aus und sucht Bau-, Sanierungs- und Wohnungsunternehmen für erste serielle Fassadenprojekte. Ihr Projekt kann hier stehen."}]},"other_section":{"eyebrow":"Neubauten","h2":"Weitere Projekte","cards":[{"tag":"Pärnu, Estland","title":"Stroomi Rannahoone","desc":"Gebäude am Strand, errichtet mit EstNor-Element- und Fassadentechnik."},{"tag":"Oslo, Norwegen","title":"Mehrfamilienhaus in Oslo","desc":"Mehrgeschossiges Wohngebäude, errichtet aus werksfertigen EstNor-Modulen."},{"tag":"Schweden","title":"Einfamilienhaus aus Elementen","desc":"Großes Einfamilienhaus, errichtet mit werksgefertigten Außen- und Innenelementen."},{"tag":"Estland","title":"Ferienhaus-Siedlung","desc":"In Kiili gefertigte modulare Ferienhäuser, komplett ausgestattet an die estnische Küste geliefert."}]},"context_left":{"eyebrow":"Einordnung","h2":"Was diese Referenzen zeigen","p":"Die serielle Fassadensanierung im bewohnten Zustand ist bei EstNor keine Ankündigung, sondern laufende Fertigung: standardisierte Elemente, wiederkehrende Gebäudetypen, Montage in Wochen. Für Deutschland geht es jetzt darum, diese Fertigung mit lokalen Partnern auf konkrete Quartiere zu übertragen."},"context_right":{"eyebrow":"Ihr Projekt","h2":"Referenz Nummer eins in Deutschland","p":"Wenn Sie ein serielles Fassadenprojekt planen und einen Fertigungspartner suchen, sprechen wir über Gebäudetypen, Stückzahlen und Zeitplan.","button":"Projekt anfragen"},"cta":{"h2":"Haben Sie ein eigenes Projekt?","body":"Erzählen Sie uns davon — wir empfehlen die passende EstNor-Bauweise.","button":"Kontakt aufnehmen"}}') ON DUPLICATE KEY UPDATE content = VALUES(content);
INSERT INTO i18n_strings (lang_code, section, content) VALUES ('sv', 'page:projects', '{"meta":{"title":"Projekt | EstNor","desc":"EstNors byggnads- och renoveringsprojekt i Estland, Norge och Sverige."},"hero":{"crumb":"Startsida","label":"Projekt","eyebrow":"Projekt","h1":"Nybyggnation och renovering sida vid sida","lead":"Ett urval av EstNors husbyggen och fasadrenoveringsprojekt i Estland, Norge, Sverige och därutöver."},"references_section":{"eyebrow":"Modernisering","h2":"Referenser för modernisering","projects":[{"svg":"<svg viewBox=\\"0 0 200 150\\" xmlns=\\"http://www.w3.org/2000/svg\\"><rect width=\\"200\\" height=\\"150\\" fill=\\"#e9efe7\\"/><g fill=\\"none\\" stroke=\\"#1f4d3a\\" stroke-width=\\"2\\"><rect x=\\"20\\" y=\\"20\\" width=\\"26\\" height=\\"28\\" rx=\\"2\\"/><rect x=\\"24\\" y=\\"25\\" width=\\"9\\" height=\\"18\\" fill=\\"#1f4d3a\\" opacity=\\".25\\"/><rect x=\\"52\\" y=\\"20\\" width=\\"26\\" height=\\"28\\" rx=\\"2\\"/><rect x=\\"56\\" y=\\"25\\" width=\\"9\\" height=\\"18\\" fill=\\"#1f4d3a\\" opacity=\\".25\\"/><rect x=\\"84\\" y=\\"20\\" width=\\"26\\" height=\\"28\\" rx=\\"2\\"/><rect x=\\"88\\" y=\\"25\\" width=\\"9\\" height=\\"18\\" fill=\\"#1f4d3a\\" opacity=\\".25\\"/><rect x=\\"20\\" y=\\"54\\" width=\\"26\\" height=\\"28\\" rx=\\"2\\"/><rect x=\\"24\\" y=\\"59\\" width=\\"9\\" height=\\"18\\" fill=\\"#1f4d3a\\" opacity=\\".25\\"/><rect x=\\"52\\" y=\\"54\\" width=\\"26\\" height=\\"28\\" rx=\\"2\\"/><rect x=\\"56\\" y=\\"59\\" width=\\"9\\" height=\\"18\\" fill=\\"#1f4d3a\\" opacity=\\".25\\"/><rect x=\\"84\\" y=\\"54\\" width=\\"26\\" height=\\"28\\" rx=\\"2\\"/><rect x=\\"88\\" y=\\"59\\" width=\\"9\\" height=\\"18\\" fill=\\"#1f4d3a\\" opacity=\\".25\\"/></g></svg>","meta":"Estland · 2022–2027","title":"KredEx-pilotprogram för seriell renovering","tags":["Fasadelement","Pilotprogram","Med boende kvar"],"desc":"Statligt pilotprogram för fabriksbaserad renovering av bostadshus. EstNor var den första deltagande elementtillverkaren och levererade störst volym fasadelement i programmet.","stats":[{"value":"12","label":"flerbostadshus"},{"value":"1:a","label":"deltagande tillverkare"}],"addresses_label":"Renoverade byggnader:","addresses":["Kooli 5, Sindi","Kotka 8, Tallinn","Muldvalge 1, Tallinn","Nisu 3, Tallinn","Pallasti 10, Tallinn","Pärnu mnt. 133, Tallinn","Riia 80, Pärnu","Turu 15, Tartu","Ojasoo 6, Kuressaare","Anne 2, Tartu","Lasteaia 2, Kehtna","Tule 4, Saue"]},{"svg":"<svg viewBox=\\"0 0 200 150\\" xmlns=\\"http://www.w3.org/2000/svg\\"><rect width=\\"200\\" height=\\"150\\" fill=\\"#e9efe7\\"/><path d=\\"M40 55 L100 25 L160 55 Z\\" fill=\\"#dd8a2c\\"/><rect x=\\"45\\" y=\\"55\\" width=\\"110\\" height=\\"80\\" fill=\\"none\\" stroke=\\"#1f4d3a\\" stroke-width=\\"2\\"/><g fill=\\"#1f4d3a\\" opacity=\\".25\\"><rect x=\\"58\\" y=\\"68\\" width=\\"18\\" height=\\"22\\"/><rect x=\\"91\\" y=\\"68\\" width=\\"18\\" height=\\"22\\"/><rect x=\\"124\\" y=\\"68\\" width=\\"18\\" height=\\"22\\"/><rect x=\\"58\\" y=\\"100\\" width=\\"18\\" height=\\"22\\"/><rect x=\\"124\\" y=\\"100\\" width=\\"18\\" height=\\"22\\"/></g><rect x=\\"91\\" y=\\"100\\" width=\\"18\\" height=\\"35\\" fill=\\"#1f4d3a\\" opacity=\\".4\\"/></svg>","meta":"Tallinn, Estland","title":"Nature Hub — miljöbyggnad","tags":["Fasad- & takelement","Förmonterade fönster"],"desc":"Till en av Estlands största trähusbyggnader levererade EstNor cirka 8 000 m² prefabricerade fasad- och takelement — inklusive fabriksmonterade fönster.","stats":[{"value":"~8 000 m²","label":"elementyta"},{"value":"Fabrik","label":"fönstermontage"}]},{"svg":"<svg viewBox=\\"0 0 200 150\\" xmlns=\\"http://www.w3.org/2000/svg\\"><rect width=\\"200\\" height=\\"150\\" fill=\\"#e9efe7\\"/><rect x=\\"45\\" y=\\"35\\" width=\\"110\\" height=\\"95\\" fill=\\"none\\" stroke=\\"#b96f1c\\" stroke-width=\\"2\\" stroke-dasharray=\\"7 6\\"/><text x=\\"100\\" y=\\"90\\" text-anchor=\\"middle\\" font-family=\\"Bricolage Grotesque, sans-serif\\" font-size=\\"15\\" fill=\\"#b96f1c\\">?</text></svg>","meta":"Nya marknader · under förberedelse","title":"Fler EstNor-projekt på gång","tags":["Söker partners","Flerbostadshus"],"desc":"EstNor bygger ut tillverkningskapaciteten för nya exportmarknader och söker bygg-, renoverings- och bostadsföretag för nästa seriella fasadprojekt. Ert projekt kan stå här."}]},"other_section":{"eyebrow":"Nybyggnation","h2":"Övriga projekt","cards":[{"tag":"Pärnu, Estland","title":"Stroomi Rannahoone","desc":"En byggnad vid havet i Pärnu, byggd med EstNors element- och fasadteknik."},{"tag":"Oslo, Norge","title":"Hyreshus i Oslo","desc":"Ett flerbostadshus uppfört med EstNors fabrikstillverkade moduler."},{"tag":"Sverige","title":"Villa i elementbyggnad","desc":"En större villa byggd med fabrikstillverkade ytter- och innerelement."},{"tag":"Estland","title":"Fritidshusområde","desc":"Ett kluster av modulära fritidshus tillverkade i Kiili, levererade färdigställda till estniska kusten."}]},"context_left":{"eyebrow":"Sammanhang","h2":"Vad dessa projekt visar","p":"För EstNor är seriell fasadrenovering med boende kvar inte ett löfte utan pågående produktion: standardiserade element, återkommande byggnadstyper, montage på veckor. Nästa steg är att föra över denna produktion till nya marknader tillsammans med lokala partners."},"context_right":{"eyebrow":"Ert projekt","h2":"Bli nästa referens","p":"Om ni planerar ett seriellt fasadprojekt och söker en tillverkningspartner, låt oss diskutera byggnadstyper, antal och tidsplan.","button":"Diskutera ett projekt"},"cta":{"h2":"Har ni ett eget projekt?","body":"Berätta om det så föreslår vi rätt EstNor-byggmetod.","button":"Kontakta oss"}}') ON DUPLICATE KEY UPDATE content = VALUES(content);
INSERT INTO i18n_strings (lang_code, section, content) VALUES ('nb', 'page:projects', '{"meta":{"title":"Prosjekter | EstNor","desc":"EstNors bygge- og rehabiliteringsprosjekter i Estland, Norge og Sverige."},"hero":{"crumb":"Forsiden","label":"Prosjekter","eyebrow":"Prosjekter","h1":"Nybygg og rehabilitering side om side","lead":"Et utvalg av EstNors husbygg og fasaderehabiliteringsprosjekter i Estland, Norge, Sverige og utover."},"references_section":{"eyebrow":"Modernisering","h2":"Referanser for modernisering","projects":[{"svg":"<svg viewBox=\\"0 0 200 150\\" xmlns=\\"http://www.w3.org/2000/svg\\"><rect width=\\"200\\" height=\\"150\\" fill=\\"#e9efe7\\"/><g fill=\\"none\\" stroke=\\"#1f4d3a\\" stroke-width=\\"2\\"><rect x=\\"20\\" y=\\"20\\" width=\\"26\\" height=\\"28\\" rx=\\"2\\"/><rect x=\\"24\\" y=\\"25\\" width=\\"9\\" height=\\"18\\" fill=\\"#1f4d3a\\" opacity=\\".25\\"/><rect x=\\"52\\" y=\\"20\\" width=\\"26\\" height=\\"28\\" rx=\\"2\\"/><rect x=\\"56\\" y=\\"25\\" width=\\"9\\" height=\\"18\\" fill=\\"#1f4d3a\\" opacity=\\".25\\"/><rect x=\\"84\\" y=\\"20\\" width=\\"26\\" height=\\"28\\" rx=\\"2\\"/><rect x=\\"88\\" y=\\"25\\" width=\\"9\\" height=\\"18\\" fill=\\"#1f4d3a\\" opacity=\\".25\\"/><rect x=\\"20\\" y=\\"54\\" width=\\"26\\" height=\\"28\\" rx=\\"2\\"/><rect x=\\"24\\" y=\\"59\\" width=\\"9\\" height=\\"18\\" fill=\\"#1f4d3a\\" opacity=\\".25\\"/><rect x=\\"52\\" y=\\"54\\" width=\\"26\\" height=\\"28\\" rx=\\"2\\"/><rect x=\\"56\\" y=\\"59\\" width=\\"9\\" height=\\"18\\" fill=\\"#1f4d3a\\" opacity=\\".25\\"/><rect x=\\"84\\" y=\\"54\\" width=\\"26\\" height=\\"28\\" rx=\\"2\\"/><rect x=\\"88\\" y=\\"59\\" width=\\"9\\" height=\\"18\\" fill=\\"#1f4d3a\\" opacity=\\".25\\"/></g></svg>","meta":"Estland · 2022–2027","title":"KredEx-pilotprogram for seriell rehabilitering","tags":["Fasadeelementer","Pilotprogram","Med beboere boende"],"desc":"Statlig pilotprogram for fabrikkbasert rehabilitering av boligbygg. EstNor var den første deltakende elementprodusenten og leverte størst volum fasadeelementer i programmet.","stats":[{"value":"12","label":"leilighetsbygg"},{"value":"1.","label":"deltakende produsent"}],"addresses_label":"Rehabiliterte bygg:","addresses":["Kooli 5, Sindi","Kotka 8, Tallinn","Muldvalge 1, Tallinn","Nisu 3, Tallinn","Pallasti 10, Tallinn","Pärnu mnt. 133, Tallinn","Riia 80, Pärnu","Turu 15, Tartu","Ojasoo 6, Kuressaare","Anne 2, Tartu","Lasteaia 2, Kehtna","Tule 4, Saue"]},{"svg":"<svg viewBox=\\"0 0 200 150\\" xmlns=\\"http://www.w3.org/2000/svg\\"><rect width=\\"200\\" height=\\"150\\" fill=\\"#e9efe7\\"/><path d=\\"M40 55 L100 25 L160 55 Z\\" fill=\\"#dd8a2c\\"/><rect x=\\"45\\" y=\\"55\\" width=\\"110\\" height=\\"80\\" fill=\\"none\\" stroke=\\"#1f4d3a\\" stroke-width=\\"2\\"/><g fill=\\"#1f4d3a\\" opacity=\\".25\\"><rect x=\\"58\\" y=\\"68\\" width=\\"18\\" height=\\"22\\"/><rect x=\\"91\\" y=\\"68\\" width=\\"18\\" height=\\"22\\"/><rect x=\\"124\\" y=\\"68\\" width=\\"18\\" height=\\"22\\"/><rect x=\\"58\\" y=\\"100\\" width=\\"18\\" height=\\"22\\"/><rect x=\\"124\\" y=\\"100\\" width=\\"18\\" height=\\"22\\"/></g><rect x=\\"91\\" y=\\"100\\" width=\\"18\\" height=\\"35\\" fill=\\"#1f4d3a\\" opacity=\\".4\\"/></svg>","meta":"Tallinn, Estland","title":"Nature Hub — miljøbygg","tags":["Fasade- & takelementer","Forhåndsmonterte vinduer"],"desc":"Til en av Estlands største trebygninger leverte EstNor rundt 8000 m² prefabrikkerte fasade- og takelementer — inkludert fabrikkmonterte vinduer.","stats":[{"value":"~8000 m²","label":"elementareal"},{"value":"Fabrikk","label":"vindusmontasje"}]},{"svg":"<svg viewBox=\\"0 0 200 150\\" xmlns=\\"http://www.w3.org/2000/svg\\"><rect width=\\"200\\" height=\\"150\\" fill=\\"#e9efe7\\"/><rect x=\\"45\\" y=\\"35\\" width=\\"110\\" height=\\"95\\" fill=\\"none\\" stroke=\\"#b96f1c\\" stroke-width=\\"2\\" stroke-dasharray=\\"7 6\\"/><text x=\\"100\\" y=\\"90\\" text-anchor=\\"middle\\" font-family=\\"Bricolage Grotesque, sans-serif\\" font-size=\\"15\\" fill=\\"#b96f1c\\">?</text></svg>","meta":"Nye markeder · under forberedelse","title":"Flere EstNor-prosjekter på vei","tags":["Søker partnere","Leilighetsbygg"],"desc":"EstNor bygger ut produksjonskapasiteten for nye eksportmarkeder og søker bygg-, rehabiliterings- og boligselskaper for de neste serielle fasadeprosjektene. Prosjektet deres kan stå her."}]},"other_section":{"eyebrow":"Nybygg","h2":"Andre prosjekter","cards":[{"tag":"Pärnu, Estland","title":"Stroomi Rannahoone","desc":"En bygning ved sjøen i Pärnu, bygget med EstNors element- og fasadeteknikk."},{"tag":"Oslo, Norge","title":"Leilighetsbygg i Oslo","desc":"Et leilighetsbygg oppført med EstNors fabrikkferdige moduler."},{"tag":"Sverige","title":"Enebolig i elementbygg","desc":"En stor enebolig bygget med fabrikkproduserte ytter- og innerelementer."},{"tag":"Estland","title":"Hytteutbygging","desc":"En klynge modulære hytter produsert i Kiili, levert ferdigstilt til den estiske kysten."}]},"context_left":{"eyebrow":"Sammenheng","h2":"Hva disse prosjektene viser","p":"For EstNor er seriell fasaderehabilitering med beboere boende ikke en kunngjøring, men løpende produksjon: standardiserte elementer, gjentakende bygningstyper, montasje på uker. Neste steg er å overføre denne produksjonen til nye markeder sammen med lokale partnere."},"context_right":{"eyebrow":"Prosjektet deres","h2":"Bli den neste referansen","p":"Hvis dere planlegger et serielt fasadeprosjekt og søker en produksjonspartner, la oss diskutere bygningstyper, antall og tidsplan.","button":"Diskuter et prosjekt"},"cta":{"h2":"Har dere et eget prosjekt?","body":"Fortell oss om det, så foreslår vi riktig EstNor-byggemetode.","button":"Kontakt oss"}}') ON DUPLICATE KEY UPDATE content = VALUES(content);
INSERT INTO i18n_strings (lang_code, section, content) VALUES ('et', 'page:serial-renovation-facade-elements', '{"meta":{"title":"Fassaadielement | EstNor","desc":"Fassaadielemendi ülesehitus, tootmisaste ja paigaldus: puitkarkass, soojustus, eelpaigaldatud aknad, ventilatsioon ja viimistletud pind."},"hero":{"crumb":"Avaleht","parent_label":"Tehaseline renoveerimine","label":"Fassaadielement","eyebrow":"Toode","h1":"Fassaadielement — valmis sein paljude eritööde asemel","lead":"Iga element on kandev puitkarkasskonstruktsioon, mis valmib tehases ligikaudu 90% ulatuses — soojustatud, akendega, ventilatsioonitorustikuga ja viimistletud pinnaga. Objektil tuleb see vaid paigaldada ja ühendada."},"buildup":{"h2":"Elemendi ülesehitus","items":["Kandev puitkarkasskonstruktsioon, digitaalselt projekteeritud BIM-mudeli järgi","Soojustus (mineraalvill) elemendi sees, minimaalsete külmasildadega","Tuule- ja aurutõke, tehases liimitud","Energiatõhusad PVC aknad, täielikult paigaldatud ja reguleeritud","Ventilatsioonitorud juhitud läbi elemendi vastavalt projektile","Fassaadiplaat / kate eelpaigaldatud — pind viimistletud tehases"]},"prefab":{"eyebrow":"Tootmisaste","h2":"Miks 90% tehases on otsustava tähtsusega","cards":[{"title":"Ilmastikukindel","desc":"Tootmine hallis — ei mingit seisakut vihma, härmatise või tuule tõttu."},{"title":"Ühtlane kvaliteet","desc":"Kontrollitud tingimused, korratavad protsessid, vähem ümbertegemist."},{"title":"Tellinguid pole vaja","desc":"Elemendid paigaldatakse väljastpoolt — ilma tellinguteta, korteritesse ligipääsu vajaduseta."},{"title":"Vähem inimesi objektil","desc":"Töö liigub tehasesse — piisab väikesest paigaldusmeeskonnast."},{"title":"Renoveerimine elanikega majas","desc":"Elanikud jäävad korteritesse; häiring piirdub päevade, mitte kuudega."},{"title":"Lühike ehitusaeg","desc":"Mitme trepikojaga hoone umbes 3–4 nädalaga peaaegu aasta asemel."}]},"install":{"eyebrow":"Paigaldus objektil","h2":"Üheksa sammu uue fassaadini","steps":[{"num":"1","title":"3D-skaneerimine","desc":"Andmete kogumine maapinnalt ja drooniga."},{"num":"2","title":"BIM-mudel","desc":"Punktipilvest saab täpne mõõtudega mudel."},{"num":"3","title":"Ettevalmistus","desc":"Kronsteinid ja alusvööd olemasolevale konstruktsioonile."},{"num":"4","title":"Nurgaelemendid","desc":"Esimeste elementide paigaldamine hoone nurkadesse."},{"num":"5","title":"Reamontaaž","desc":"Element elemendi haaval, rida rea haaval."},{"num":"6","title":"Täiskate","desc":"Fassaad on täielikult elementidega kaetud."},{"num":"7","title":"Ventilatsioon","desc":"Ventilatsioonitorude ühendamine."},{"num":"8","title":"Trepikoda","desc":"Trepikoja elementide paigaldus."},{"num":"9","title":"Lõpetamine","desc":"Vuugid, vihmaveesüsteem, katuseühendus."}]},"logistics":{"eyebrow":"Logistika","h2":"Eestist — Euroopa Liidu sees","body":"Tootmine Kiili tehases Tallinna lähedal. ELi liikmesriigina puuduvad tolliformaalsused; teed üle Läänemere ja maismaad pidi on hästi väljaarendatud. Elemendid sorteeritakse paigaldusjärjekorra järgi ja tarnitakse just-in-time põhimõttel."},"quality":{"eyebrow":"Kvaliteet ja sertifikaadid","items":["ISO 9001 kvaliteedijuhtimine","CE-märgistus, Euroopa tehniline hinnang (EOTA)","Eesti Puitmajaliidu liige","Projektipõhine dokumentatsioon kohalike nõuete järgi soovi korral"],"callout_label":"Täpsustamisel:","callout_text":"konkreetsed ehitusjärelevalve nõuded ja tuleohutusklass sihtriigi jaoks tuleb enne projekti algust EstNoriga kokku leppida."},"cta":{"h2":"Räägime su projekti elementidest","body":"Saada meile hoone tüüp, ehitusaasta ja fassaadipind — anname esialgse hinnangu elementide ja tarneaja kohta.","button":"Võta ühendust"}}') ON DUPLICATE KEY UPDATE content = VALUES(content);
INSERT INTO i18n_strings (lang_code, section, content) VALUES ('en', 'page:serial-renovation-facade-elements', '{"meta":{"title":"Facade Elements — EstNor","desc":"Build-up, degree of prefabrication and installation of EstNor facade elements: timber frame, insulation, pre-installed windows, ventilation routing and a finished facade surface."},"hero":{"crumb":"Home","parent_label":"Serial Renovation","label":"Facade Elements","eyebrow":"The product","h1":"The facade element: a finished wall instead of many separate trades","lead":"Each element is a load-bearing timber-frame structure completed to around 90% in the factory — insulated, with windows, ventilation routing and a finished surface. On site it only has to be set in place and connected."},"buildup":{"h2":"Element build-up","items":["Load-bearing timber-frame structure, digitally engineered from the BIM model","Insulation (mineral wool) within the element, with minimal thermal bridging","Wind and vapour barrier, factory-bonded","Energy-efficient PVC windows, fully installed and adjusted","Ventilation ducts routed through the element as designed","Cladding panel / facing pre-fitted — surface finished at the factory"]},"prefab":{"eyebrow":"Degree of prefabrication","h2":"Why 90% in the factory is the decisive point","cards":[{"title":"Weather-independent","desc":"Production in the hall — no work stoppage in rain, frost or wind."},{"title":"Consistent quality","desc":"Controlled conditions, repeatable processes, less rework."},{"title":"No scaffolding","desc":"Elements are set from the outside — no scaffolding, no access to flats."},{"title":"Fewer people on site","desc":"The work moves into the factory — a small installation team is enough."},{"title":"Renovatable while occupied","desc":"Tenants stay in their flats; disruption is limited to days rather than months."},{"title":"Short construction time","desc":"A building with several stairwells in about 3–4 weeks instead of nearly a year."}]},"install":{"eyebrow":"On-site installation","h2":"Nine steps to the new envelope","steps":[{"num":"1","title":"3D scan","desc":"Capture from the ground and by drone."},{"num":"2","title":"BIM model","desc":"The point cloud becomes a dimensionally accurate model."},{"num":"3","title":"Preparation","desc":"Brackets and base rails on the existing structure."},{"num":"4","title":"Corner elements","desc":"Setting the first elements at the building corners."},{"num":"5","title":"Row installation","desc":"Element by element, row by row."},{"num":"6","title":"Full coverage","desc":"The facade is completely covered with elements."},{"num":"7","title":"Ventilation","desc":"Connecting the ventilation ducts."},{"num":"8","title":"Stairwell","desc":"Installing the stairwell elements."},{"num":"9","title":"Completion","desc":"Joints, rainwater system, roof connection."}]},"logistics":{"eyebrow":"Logistics","h2":"From Estonia — within the EU","body":"Production at the factory in Kiili near Tallinn. As an EU member state there are no customs formalities; the routes across the Baltic Sea and overland are well established. Elements are sorted for installation and delivered just in time."},"quality":{"eyebrow":"Quality & certification","items":["Quality management to ISO 9001","CE marking, European Technical Assessment (EOTA)","Ü-mark (declaration of conformity) for use in Germany","Member of the Estonian Woodhouse Association (Puitmajaliit)","Project-specific documentation to local requirements on request"],"callout_label":"To be confirmed per project:","callout_text":"specific building-authority approvals and fire classification for the target country should be agreed with EstNor before a project starts."},"cta":{"h2":"Discuss the element build-up for your project","body":"Send us the building type, year of construction and facade area — we\'ll estimate element types, production effort and delivery time.","button":"Contact EstNor"}}') ON DUPLICATE KEY UPDATE content = VALUES(content);
INSERT INTO i18n_strings (lang_code, section, content) VALUES ('de', 'page:serial-renovation-facade-elements', '{"meta":{"title":"Fassadenelemente von EstNor | EstNor","desc":"Aufbau, Vorfertigungsgrad und Montage der EstNor-Fassadenelemente: Holzrahmen, Dämmung, vormontierte Fenster, Lüftungsführung und fertige Fassadenoberfläche."},"hero":{"crumb":"Startseite","parent_label":"Serielle Sanierung","label":"Fassadenelemente","eyebrow":"Das Produkt","h1":"Das Fassadenelement: eine fertige Wand statt vieler Einzelgewerke","lead":"Jedes Element ist eine tragfähige Holzrahmenkonstruktion, die im Werk zu rund 90 % fertiggestellt wird — gedämmt, mit Fenstern, Lüftungsführung und fertiger Oberfläche. Auf der Baustelle wird es nur noch gesetzt und angeschlossen."},"buildup":{"h2":"Aufbau des Elements","items":["Tragende Holzrahmenkonstruktion, digital konstruiert nach BIM-Modell","Dämmung (Mineralwolle) im Element, wärmebrückenarm","Wind- und Dampfsperre, werkseitig verklebt","Energieeffiziente PVC-Fenster, fertig eingebaut und justiert","Lüftungskanäle nach Planung im Element geführt","Fassadenplatte / Bekleidung vormontiert — Oberfläche ab Werk"]},"prefab":{"eyebrow":"Fertigungsgrad","h2":"Warum 90 % im Werk der entscheidende Punkt ist","cards":[{"title":"Witterungsunabhängig","desc":"Fertigung in der Halle — kein Baustopp bei Regen, Frost oder Wind."},{"title":"Gleichbleibende Qualität","desc":"Kontrollierte Bedingungen, wiederholbare Prozesse, weniger Nacharbeit."},{"title":"Kein Gerüst","desc":"Elemente werden von außen gesetzt — ohne Einrüstung, ohne Zugang zu Wohnungen."},{"title":"Weniger Personal vor Ort","desc":"Die Arbeit verlagert sich ins Werk — ein kleines Montageteam genügt."},{"title":"Bewohnt sanierbar","desc":"Mieter bleiben in der Wohnung; die Belastung ist auf Tage statt Monate begrenzt."},{"title":"Kurze Bauzeit","desc":"Ein Gebäude mit mehreren Treppenhäusern in rund 3–4 Wochen statt fast einem Jahr."}]},"install":{"eyebrow":"Montage vor Ort","h2":"In neun Schritten zur neuen Hülle","steps":[{"num":"1","title":"3D-Scan","desc":"Erfassung vom Boden und per Drohne."},{"num":"2","title":"BIM-Modell","desc":"Punktwolke wird zum maßhaltigen Modell."},{"num":"3","title":"Vorbereitung","desc":"Konsolen und Fußschwellen am Bestand."},{"num":"4","title":"Eckelemente","desc":"Setzen der ersten Elemente an den Gebäudeecken."},{"num":"5","title":"Reihenmontage","desc":"Element für Element, Reihe für Reihe."},{"num":"6","title":"Vollflächig","desc":"Die Fassade ist komplett mit Elementen bedeckt."},{"num":"7","title":"Lüftung","desc":"Anschluss der Lüftungsrohre."},{"num":"8","title":"Treppenhaus","desc":"Montage der Treppenhauselemente."},{"num":"9","title":"Abschluss","desc":"Fugen, Regenwassersystem, Dachanschluss."}]},"logistics":{"eyebrow":"Logistik","h2":"Aus Estland nach Deutschland — innerhalb der EU","body":"Produktion im Werk in Kiili bei Tallinn. Als EU-Mitgliedstaat entfallen Zollformalitäten; die Wege über die Ostsee und auf dem Landweg sind gut erschlossen. Elemente werden montagegerecht sortiert und just-in-time angeliefert."},"quality":{"eyebrow":"Qualität & Nachweise","items":["Qualitätsmanagement nach ISO 9001","CE-Kennzeichnung, europäische technische Bewertung (EOTA)","Ü-Zeichen (Übereinstimmungszeichen) für den Einsatz in Deutschland","Mitglied im estnischen Holzhausverband (Puitmajaliit)","Projektbezogene Nachweise nach deutschen Anforderungen auf Anfrage"],"callout_label":"Zu ergänzen:","callout_text":"konkrete bauaufsichtliche Nachweise / Zulassungen für den Einsatz in Deutschland (z. B. abZ/aBG, Brandschutzklassifizierung) vor Livegang mit EstNor abstimmen."},"cta":{"h2":"Elementaufbau für Ihr Projekt durchsprechen","body":"Schicken Sie uns Gebäudetyp, Baujahr und Fassadenfläche — wir schätzen Elementtypen, Fertigungsaufwand und Lieferzeit ein.","button":"Kontakt aufnehmen"}}') ON DUPLICATE KEY UPDATE content = VALUES(content);
INSERT INTO i18n_strings (lang_code, section, content) VALUES ('sv', 'page:serial-renovation-facade-elements', '{"meta":{"title":"Fasad- och takelement | EstNor","desc":"Uppbyggnad, förtillverkningsgrad och montage av EstNors fasadelement: trästomme, isolering, förmonterade fönster, ventilation och färdig fasadyta."},"hero":{"crumb":"Startsida","parent_label":"Modernisering","label":"Fasad- och takelement","eyebrow":"Produkten","h1":"Fasadelementet: en färdig vägg istället för många separata hantverk","lead":"Varje element är en bärande trästommekonstruktion, färdigställd till cirka 90 % i fabriken — isolerad, med fönster, ventilation och färdig yta. På plats behöver den bara sättas på plats och anslutas."},"buildup":{"h2":"Elementets uppbyggnad","items":["Bärande trästommekonstruktion, digitalt konstruerad från BIM-modellen","Isolering (mineralull) i elementet, med minimal köldbrygga","Vind- och ångspärr, fabrikslimmad","Energieffektiva PVC-fönster, helt monterade och injusterade","Ventilationskanaler dragna genom elementet enligt ritning","Fasadskiva/beklädnad förmonterad — yta färdigställd i fabriken"]},"prefab":{"eyebrow":"Förtillverkningsgrad","h2":"Varför 90 % i fabriken är avgörande","cards":[{"title":"Väderoberoende","desc":"Tillverkning inomhus — inget stopp vid regn, frost eller blåst."},{"title":"Jämn kvalitet","desc":"Kontrollerade förhållanden, repeterbara processer, mindre efterarbete."},{"title":"Ingen byggnadsställning","desc":"Elementen sätts utifrån — utan ställning, utan tillträde till lägenheter."},{"title":"Mindre personal på plats","desc":"Arbetet flyttas till fabriken — ett litet montageteam räcker."},{"title":"Renoveras med boende kvar","desc":"Hyresgästerna stannar i lägenheten; störningen begränsas till dagar snarare än månader."},{"title":"Kort byggtid","desc":"Ett hus med flera trapphus på cirka 3–4 veckor istället för nästan ett år."}]},"install":{"eyebrow":"Montage på plats","h2":"Nio steg till det nya klimatskalet","steps":[{"num":"1","title":"3D-skanning","desc":"Insamling från marken och med drönare."},{"num":"2","title":"BIM-modell","desc":"Punktmolnet blir en måttriktig modell."},{"num":"3","title":"Förberedelse","desc":"Konsoler och grundsyllar på befintlig stomme."},{"num":"4","title":"Hörnelement","desc":"Första elementen sätts i byggnadens hörn."},{"num":"5","title":"Radmontage","desc":"Element för element, rad för rad."},{"num":"6","title":"Heltäckande","desc":"Fasaden är helt täckt med element."},{"num":"7","title":"Ventilation","desc":"Anslutning av ventilationskanaler."},{"num":"8","title":"Trapphus","desc":"Montage av trapphuselement."},{"num":"9","title":"Avslutning","desc":"Fogar, dagvattensystem, takanslutning."}]},"logistics":{"eyebrow":"Logistik","h2":"Från Estland — inom EU","body":"Produktion vid fabriken i Kiili nära Tallinn. Som EU-medlemsstat finns inga tullformaliteter; vägarna över Östersjön och landvägen är väl utbyggda. Elementen sorteras för montage och levereras just-in-time."},"quality":{"eyebrow":"Kvalitet & certifiering","items":["Kvalitetsledning enligt ISO 9001","CE-märkning, europeisk teknisk bedömning (EOTA)","Medlem i Estniska Trähusförbundet","Projektspecifik dokumentation efter lokala krav på begäran"],"callout_label":"Att bekräfta per projekt:","callout_text":"specifika byggmyndighetsgodkännanden och brandklassificering för målmarknaden bör stämmas av med EstNor innan ett projekt påbörjas."},"cta":{"h2":"Diskutera elementuppbyggnaden för ert projekt","body":"Skicka byggnadstyp, byggår och fasadyta — vi uppskattar elementtyper, tillverkningsinsats och leveranstid.","button":"Kontakta oss"}}') ON DUPLICATE KEY UPDATE content = VALUES(content);
INSERT INTO i18n_strings (lang_code, section, content) VALUES ('nb', 'page:serial-renovation-facade-elements', '{"meta":{"title":"Fasade- og takelementer | EstNor","desc":"Oppbygning, forhåndsproduksjonsgrad og montasje av EstNors fasadeelementer: trekonstruksjon, isolasjon, forhåndsmonterte vinduer, ventilasjon og ferdig fasadeoverflate."},"hero":{"crumb":"Forsiden","parent_label":"Modernisering","label":"Fasade- og takelementer","eyebrow":"Produktet","h1":"Fasadeelementet: en ferdig vegg i stedet for mange enkeltfag","lead":"Hvert element er en bærende trekonstruksjon, ferdigstilt til rundt 90 % i fabrikken — isolert, med vinduer, ventilasjon og ferdig overflate. På byggeplassen skal det bare settes på plass og tilkobles."},"buildup":{"h2":"Elementets oppbygning","items":["Bærende trekonstruksjon, digitalt konstruert fra BIM-modellen","Isolasjon (mineralull) i elementet, med minimal kuldebro","Vind- og dampsperre, fabrikklimet","Energieffektive PVC-vinduer, ferdig montert og justert","Ventilasjonskanaler ført gjennom elementet etter plan","Fasadeplate/kledning forhåndsmontert — overflate ferdigstilt i fabrikken"]},"prefab":{"eyebrow":"Forhåndsproduksjonsgrad","h2":"Hvorfor 90 % i fabrikken er avgjørende","cards":[{"title":"Værbestandig","desc":"Produksjon innendørs — ingen stopp ved regn, frost eller vind."},{"title":"Jevn kvalitet","desc":"Kontrollerte forhold, repeterbare prosesser, mindre etterarbeid."},{"title":"Ikke stillas","desc":"Elementene settes utenfra — uten stillas, uten tilgang til leiligheter."},{"title":"Mindre personell på stedet","desc":"Arbeidet flyttes til fabrikken — et lite montasjeteam er nok."},{"title":"Rehabiliteres med beboere boende","desc":"Leietakerne blir boende; belastningen begrenses til dager i stedet for måneder."},{"title":"Kort byggetid","desc":"Et bygg med flere trappeoppganger på rundt 3–4 uker i stedet for nesten et år."}]},"install":{"eyebrow":"Montasje på stedet","h2":"Ni trinn til det nye klimaskallet","steps":[{"num":"1","title":"3D-skanning","desc":"Innsamling fra bakken og med drone."},{"num":"2","title":"BIM-modell","desc":"Punktskyen blir en målnøyaktig modell."},{"num":"3","title":"Forberedelse","desc":"Konsoller og grunnsviller på eksisterende konstruksjon."},{"num":"4","title":"Hjørneelementer","desc":"De første elementene settes i byggets hjørner."},{"num":"5","title":"Radmontasje","desc":"Element for element, rad for rad."},{"num":"6","title":"Full dekning","desc":"Fasaden er helt dekket med elementer."},{"num":"7","title":"Ventilasjon","desc":"Tilkobling av ventilasjonskanaler."},{"num":"8","title":"Trappeoppgang","desc":"Montasje av trappeoppgangselementer."},{"num":"9","title":"Avslutning","desc":"Fuger, regnvannssystem, taktilkobling."}]},"logistics":{"eyebrow":"Logistikk","h2":"Fra Estland — innenfor EU","body":"Produksjon ved fabrikken i Kiili nær Tallinn. Som EU-medlemsstat bortfaller tollformaliteter; veiene over Østersjøen og på land er godt utbygd. Elementene sorteres for montasje og leveres just-in-time."},"quality":{"eyebrow":"Kvalitet & dokumentasjon","items":["Kvalitetsstyring etter ISO 9001","CE-merking, europeisk teknisk vurdering (EOTA)","Medlem av Estisk Trehusforening","Prosjektspesifikk dokumentasjon etter norske krav på forespørsel"],"callout_label":"Å bekrefte per prosjekt:","callout_text":"spesifikke godkjenninger fra bygningsmyndigheter og brannklassifisering for målmarkedet bør avklares med EstNor før et prosjekt starter."},"cta":{"h2":"Diskuter elementoppbygningen for prosjektet ditt","body":"Send oss bygningstype, byggeår og fasadeareal — vi anslår elementtyper, produksjonsinnsats og leveringstid.","button":"Kontakt oss"}}') ON DUPLICATE KEY UPDATE content = VALUES(content);
INSERT INTO i18n_strings (lang_code, section, content) VALUES ('et', 'page:serial-renovation-gallery', '{"meta":{"title":"Galerii | EstNor","desc":"Tehaselise fassaadirenoveerimise etapid piltides — skaneerimisest valmis fassaadini."},"hero":{"crumb":"Avaleht","parent_label":"Tehaseline renoveerimine","label":"Galerii","eyebrow":"Tehasest fassaadini","h1":"Renoveerimise etapid piltides","lead":"Pilguheit tehaselise fassaadirenoveerimise protsessi — skaneerimisest kuni valmis fassaadini. Illustratsioonid on visandid, pärisfotod lisatakse niipea kui need on saadaval."},"captions":["3D-skannimine","Elemendi tootmine","Fassaad enne","Paigaldus","Fassaad pärast","Valmis hoone"],"cta":{"h2":"Kas plaanid kortermaja renoveerimist?","body":"Vaata meie tehtud renoveerimisprojekte või võta otse ühendust.","button":"Vaata referentse"}}') ON DUPLICATE KEY UPDATE content = VALUES(content);
INSERT INTO i18n_strings (lang_code, section, content) VALUES ('en', 'page:serial-renovation-gallery', '{"meta":{"title":"Gallery — Serial Renovation | EstNor","desc":"The serial facade renovation process in pictures — from scanning to the finished facade."},"hero":{"crumb":"Home","parent_label":"Serial Renovation","label":"Gallery","eyebrow":"From factory to facade","h1":"The renovation process in pictures","lead":"A visual look at the serial facade renovation process — from scanning to the finished facade. The illustrations are sketches; real photos will be added as soon as they are available."},"captions":["3D scanning","Element production","Facade before","Installation","Facade after","Finished building"],"cta":{"h2":"Planning to renovate an apartment building?","body":"Browse our completed renovation projects, or get in touch directly.","button":"See references"}}') ON DUPLICATE KEY UPDATE content = VALUES(content);
INSERT INTO i18n_strings (lang_code, section, content) VALUES ('de', 'page:serial-renovation-gallery', '{"meta":{"title":"Galerie — Serielle Sanierung | EstNor","desc":"Der Prozess der seriellen Fassadensanierung in Bildern — vom Scan bis zur fertigen Fassade."},"hero":{"crumb":"Startseite","parent_label":"Serielle Sanierung","label":"Galerie","eyebrow":"Vom Werk zur Fassade","h1":"Der Sanierungsprozess in Bildern","lead":"Ein Einblick in den Prozess der seriellen Fassadensanierung — vom Scan bis zur fertigen Fassade. Die Illustrationen sind Skizzen — echte Fotos werden ergänzt, sobald sie vorliegen."},"captions":["3D-Scan","Elementfertigung","Fassade vorher","Montage","Fassade nachher","Fertiges Gebäude"],"cta":{"h2":"Planen Sie die Sanierung eines Mehrfamilienhauses?","body":"Sehen Sie sich unsere abgeschlossenen Sanierungsprojekte an oder kontaktieren Sie uns direkt.","button":"Referenzen ansehen"}}') ON DUPLICATE KEY UPDATE content = VALUES(content);
INSERT INTO i18n_strings (lang_code, section, content) VALUES ('sv', 'page:serial-renovation-gallery', '{"meta":{"title":"Galleri — Modernisering | EstNor","desc":"Processen för seriell fasadrenovering i bilder — från skanning till färdig fasad."},"hero":{"crumb":"Startsida","parent_label":"Modernisering","label":"Galleri","eyebrow":"Från fabrik till fasad","h1":"Moderniseringsprocessen i bilder","lead":"En inblick i processen för seriell fasadrenovering — från skanning till färdig fasad. Illustrationerna är skisser — riktiga foton läggs till när de finns tillgängliga."},"captions":["3D-skanning","Elementtillverkning","Fasad före","Montage","Fasad efter","Färdig byggnad"],"cta":{"h2":"Planerar du att renovera ett flerbostadshus?","body":"Se våra genomförda renoveringsprojekt eller kontakta oss direkt.","button":"Se referenser"}}') ON DUPLICATE KEY UPDATE content = VALUES(content);
INSERT INTO i18n_strings (lang_code, section, content) VALUES ('nb', 'page:serial-renovation-gallery', '{"meta":{"title":"Galleri — Modernisering | EstNor","desc":"Prosessen for seriell fasaderehabilitering i bilder — fra skanning til ferdig fasade."},"hero":{"crumb":"Forsiden","parent_label":"Modernisering","label":"Galleri","eyebrow":"Fra fabrikk til fasade","h1":"Moderniseringsprosessen i bilder","lead":"Et innblikk i prosessen for seriell fasaderehabilitering — fra skanning til ferdig fasade. Illustrasjonene er skisser — ekte bilder legges til når de foreligger."},"captions":["3D-skanning","Elementproduksjon","Fasade før","Montasje","Fasade etter","Ferdig bygg"],"cta":{"h2":"Planlegger du å rehabilitere et leilighetsbygg?","body":"Se våre gjennomførte rehabiliteringsprosjekter, eller ta direkte kontakt.","button":"Se referanser"}}') ON DUPLICATE KEY UPDATE content = VALUES(content);
INSERT INTO i18n_strings (lang_code, section, content) VALUES ('et', 'page:serial-renovation', '{"meta":{"title":"Tehaseline renoveerimine | EstNor","desc":"EstNor toodab soojustatud fassaadielemente kortermajade tehaseliseks renoveerimiseks — esimene ja suurim tootja KredEx pilootprogrammis."},"hero":{"crumb":"Avaleht","label":"Tehaseline renoveerimine","eyebrow":"Tehaseline rekonstrueerimine","h1_line1":"Uue ajastu rekonstrueerimine","h1_accent":"tehases toodetud soojustatud elementidega.","lead":"Fassaadielementide tootmisel tugineb EstNor ulatuslikule teadmistepagasile ja aastakümnete pikkusele kogemusele, pakkudes parimat kompetentsi hoonete energiatõhususe tõstmisel.","cta_primary":"Võta ühendust","cta_secondary":"Fassaadielemendist lähemalt"},"why_left":{"h2":"Miks tehases toodetud elemendid","items":["90% fassaaditöödest teostatakse tehases, kontrollitud keskkonnas","Eeltoodetud elemendid tõstavad objektitöö efektiivsust","Objektitöö on tellingutevaba","Elanikele ohutu ja mugav renoveerimisviis","Lahendus vastab tuleohutusnõuetele"]},"why_right":{"h2":"EstNor pakub","items":["Maja mõõdistamine ja kinnituste tõmbetugevuse katsetused","Konstruktiivne projekteerimine (BIM-mudel)","Elementide tehaseline tootmine","Ventilatsioonikanalite paigaldus elementidesse tehases","Transport tehasest ehitusobjektile","Elementide montaaž ning montaaži eel- ja järeltööd objektil"]},"steps":{"eyebrow":"Nii see käib","h2":"Hoone skaneerimisest paigaldatud fassaadini","items":[{"title":"Skaneerimine","desc":"Vana maja 3D-skaneeritakse maapinnalt ja drooniga — tulemuseks detailne punktipilv."},{"title":"Modelleerimine","desc":"Punktipilvest valmib BIM-mudel, mille põhjal projekteeritakse uued fassaadielemendid."},{"title":"Ettevalmistus ja nurgaelemendid","desc":"Paigaldatakse kronsteinid ja alusvöö, seejärel esimesed elemendid maja nurkadesse."},{"title":"Paigaldus ja viimistlus","desc":"Elemendid paigaldatakse rida-realt, seejärel ventilatsioon, trepikoda, vihmaveesüsteem ja katuseühendus."}]},"funding_left":{"eyebrow":"KredEx rekonstrueerimistoetus 2022–2027","h2":"Riiklik toetusmeede","p1":"KredEx toetusmeetme eesmärk on rahastada korterelamute terviklikku rekonstrueerimist või küttesüsteemi asendamist taastuvenergial põhineva lahendusega. Rohkem infot: KredEx.ee.","p2":"Esimeses KredEx pilootprojektis (2022) osales EstNor väga edukalt, kindlustades 12 kortermaja fassaadielementide tootmise — kõik toodetud puitkonstruktsioonile, soojustusvillaga, uute PVC akendega ja tehases juba paigaldatud fassaadiviimistlusega. EstNor on selles programmis esimene ja mahult suurim tootja."},"funding_right":{"eyebrow":"Kiirus, mis loeb","h2":"3–4 nädalat, mitte peaaegu aasta","p":"Kui 5-korruselise ja 5 trepikojaga maja soojustamine objektil vahtpolüstürooliga võib kesta peaaegu aasta, katab meie tehases toodetud fassaadielementidega maja fassaadi vaid 3–4 nädalaga. Tellinguid ei ole vaja — need piiraksid elanike väljavaadet aknast ja kujutaksid endast turvariski kogu renoveerimise vältel.","callout_label":"Tulemus:","callout_text":"vanade kortermajade energiatõhusus paraneb kiiresti, ehitusaeg lüheneb ja hoone kasutusiga pikeneb."},"explore":{"eyebrow":"Rohkem infot","h2":"Uuri lähemalt","cards":[{"title":"Fassaadielement","desc":"Kuidas fassaadielement üles ehitatud on — mõõdistamisest kuni valmis viimistluseni.","href":"facade-elements.php"},{"title":"Tehtud projektid","desc":"KredEx programmi raames renoveeritud 12 kortermaja üle Eesti.","href":"../projects.php"}]},"cta":{"h2":"Plaanid kortermaja renoveerimist?","body":"Saada meile maja põhiandmed — ehitusaasta, korterite arv, fassaadipind — ja saad esmase hinnangu elementide tootmise kohta.","button":"Võta ühendust"}}') ON DUPLICATE KEY UPDATE content = VALUES(content);
INSERT INTO i18n_strings (lang_code, section, content) VALUES ('en', 'page:serial-renovation', '{"meta":{"title":"Serial Renovation — EstNor","desc":"Serial renovation explained: EstNor manufactures insulated facade elements for the factory-based renovation of apartment buildings — the first and largest manufacturer in the KredEx pilot programme."},"hero":{"crumb":"Home","label":"Serial Renovation","eyebrow":"Factory reconstruction","h1_line1":"A new era of reconstruction","h1_accent":"with factory-built insulated elements.","lead":"In manufacturing facade elements, EstNor draws on extensive know-how and decades of experience, offering the best expertise for raising a building\'s energy efficiency.","cta_primary":"Contact EstNor","cta_secondary":"See the facade element"},"why_left":{"h2":"Why factory-built elements","items":["90% of facade work is carried out in the factory, in a controlled environment","Prefabricated elements make on-site work far more efficient","On-site work requires no scaffolding","A safe, convenient renovation method for residents","The solution meets fire-safety requirements"]},"why_right":{"h2":"What EstNor provides","items":["Building survey and pull-out strength testing of fixings","Structural design (BIM model)","Factory production of the elements","Ventilation ducting installed into the elements at the factory","Transport from the factory to the building site","Installation of the elements, plus preparatory and follow-up work on site"]},"steps":{"eyebrow":"How it works","h2":"From building scan to installed facade","items":[{"title":"Scanning","desc":"The existing building is 3D-scanned from the ground and by drone — producing a detailed point cloud."},{"title":"Modelling","desc":"A BIM model is built from the point cloud, on which the new facade elements are designed."},{"title":"Preparation & corner elements","desc":"Brackets and a base rail are installed, then the first elements go up at the building\'s corners."},{"title":"Installation & finishing","desc":"Elements are installed row by row, then ventilation, the stairwell, the rainwater system and the roof junction."}]},"funding_left":{"eyebrow":"KredEx reconstruction grant 2022–2027","h2":"A state funding scheme","p1":"The KredEx grant scheme funds the comprehensive reconstruction of apartment buildings or the replacement of heating systems with a renewable-energy solution. More information: KredEx.ee.","p2":"EstNor took part very successfully in the first KredEx pilot project (2022), securing the production of facade elements for 12 apartment buildings — all built on a timber frame, with mineral wool insulation, new PVC windows and the facade finish already applied at the factory. EstNor is the first and largest-volume manufacturer in this programme."},"funding_right":{"eyebrow":"Speed that matters","h2":"3–4 weeks, not almost a year","p":"While insulating a 5-storey, 5-stairwell building on site with expanded polystyrene can take almost a year, our factory-built facade elements cover the same building\'s facade in just 3–4 weeks. No scaffolding is needed — it would block residents\' view from their windows and pose a safety risk for the whole renovation.","callout_label":"Result:","callout_text":"old apartment buildings gain energy efficiency quickly, construction time shortens, and the building\'s service life is extended."},"explore":{"eyebrow":"Learn more","h2":"Explore further","cards":[{"title":"Facade Elements","desc":"How the facade element is built — from survey to finished surface.","href":"facade-elements.php"},{"title":"Completed Projects","desc":"12 apartment buildings renovated across Estonia under the KredEx programme.","href":"../projects.php"}]},"cta":{"h2":"Planning to renovate an apartment building?","body":"Send us your building\'s key facts — construction year, number of apartments, facade area — and we\'ll get back to you with an initial assessment.","button":"Contact EstNor"}}') ON DUPLICATE KEY UPDATE content = VALUES(content);
INSERT INTO i18n_strings (lang_code, section, content) VALUES ('de', 'page:serial-renovation', '{"meta":{"title":"Tehaseline renoveerimine | EstNor","desc":"Serielle Sanierung: EstNor fertigt gedämmte Fassadenelemente für die werksseitige Sanierung von Mehrfamilienhäusern — erster und größter Hersteller im KredEx-Pilotprogramm."},"hero":{"crumb":"Startseite","label":"Serielle Sanierung","eyebrow":"Werksseitige Sanierung","h1_line1":"Sanierung einer neuen Ära","h1_accent":"mit im Werk gefertigten, gedämmten Elementen.","lead":"Bei der Fertigung von Fassadenelementen stützt sich EstNor auf umfassendes Fachwissen und jahrzehntelange Erfahrung und bietet beste Kompetenz zur Steigerung der Energieeffizienz von Gebäuden.","cta_primary":"Kontakt aufnehmen","cta_secondary":"Fassadenelement ansehen"},"why_left":{"h2":"Warum werksgefertigte Elemente","items":["90 % der Fassadenarbeiten erfolgen im Werk, unter kontrollierten Bedingungen","Vorgefertigte Elemente steigern die Effizienz der Arbeiten vor Ort","Die Arbeiten vor Ort kommen ohne Gerüst aus","Eine für Bewohner sichere und angenehme Sanierungsmethode","Die Lösung erfüllt die Brandschutzanforderungen"]},"why_right":{"h2":"Das bietet EstNor","items":["Gebäudevermessung und Auszugsfestigkeitsprüfungen der Befestigungen","Konstruktive Planung (BIM-Modell)","Werksseitige Fertigung der Elemente","Lüftungskanäle bereits im Werk in die Elemente eingebaut","Transport vom Werk zur Baustelle","Montage der Elemente sowie Vor- und Nacharbeiten vor Ort"]},"steps":{"eyebrow":"So funktioniert es","h2":"Vom Gebäudescan zur montierten Fassade","items":[{"title":"Scan","desc":"Das Bestandsgebäude wird vom Boden und per Drohne 3D-gescannt — Ergebnis ist eine detaillierte Punktwolke."},{"title":"Modellierung","desc":"Aus der Punktwolke entsteht ein BIM-Modell, auf dessen Grundlage die neuen Fassadenelemente geplant werden."},{"title":"Vorbereitung & Eckelemente","desc":"Konsolen und Grundschiene werden montiert, danach die ersten Elemente an den Gebäudeecken."},{"title":"Montage & Fertigstellung","desc":"Die Elemente werden Reihe für Reihe montiert, danach Lüftung, Treppenhaus, Regenwassersystem und Dachanschluss."}]},"funding_left":{"eyebrow":"KredEx-Sanierungsförderung 2022–2027","h2":"Ein staatliches Förderprogramm","p1":"Das KredEx-Förderprogramm finanziert die umfassende Sanierung von Mehrfamilienhäusern oder den Austausch der Heizungsanlage gegen eine Lösung auf Basis erneuerbarer Energie. Weitere Informationen: KredEx.ee.","p2":"Am ersten KredEx-Pilotprojekt (2022) nahm EstNor sehr erfolgreich teil und sicherte sich die Fertigung der Fassadenelemente für 12 Mehrfamilienhäuser — alle auf Holzrahmenbasis, mit Mineralwolldämmung, neuen PVC-Fenstern und bereits im Werk aufgebrachter Fassadenoberfläche. EstNor ist in diesem Programm der erste und volumenmäßig größte Hersteller."},"funding_right":{"eyebrow":"Geschwindigkeit, die zählt","h2":"3–4 Wochen statt fast einem Jahr","p":"Während die Dämmung eines fünfgeschossigen Gebäudes mit fünf Treppenhäusern vor Ort mit EPS fast ein Jahr dauern kann, verkleidet unser werksgefertigtes Fassadenelement dieselbe Fassade in nur 3–4 Wochen. Ein Gerüst ist nicht nötig — es würde den Bewohnern die Aussicht nehmen und während der gesamten Sanierung ein Sicherheitsrisiko darstellen.","callout_label":"Ergebnis:","callout_text":"Alte Mehrfamilienhäuser gewinnen schnell an Energieeffizienz, die Bauzeit verkürzt sich, und die Nutzungsdauer des Gebäudes verlängert sich."},"explore":{"eyebrow":"Mehr erfahren","h2":"Weiter erkunden","cards":[{"title":"Fassadenelemente","desc":"Wie das Fassadenelement aufgebaut ist — von der Vermessung bis zur fertigen Oberfläche.","href":"facade-elements.php"},{"title":"Abgeschlossene Projekte","desc":"12 im Rahmen des KredEx-Programms sanierte Mehrfamilienhäuser in ganz Estland.","href":"../projects.php"}]},"cta":{"h2":"Planen Sie die Sanierung eines Mehrfamilienhauses?","body":"Schicken Sie uns die wichtigsten Eckdaten Ihres Gebäudes — Baujahr, Anzahl der Wohnungen, Fassadenfläche — und Sie erhalten eine erste Einschätzung.","button":"Kontakt aufnehmen"}}') ON DUPLICATE KEY UPDATE content = VALUES(content);
INSERT INTO i18n_strings (lang_code, section, content) VALUES ('sv', 'page:serial-renovation', '{"meta":{"title":"Modernisering av flerbostadshus | EstNor","desc":"EstNor tillverkar isolerade fasadelement för fabriksbaserad modernisering av flerbostadshus — första och största tillverkaren i KredEx pilotprogram."},"hero":{"crumb":"Startsida","label":"Modernisering av flerbostadshus","eyebrow":"Fabriksbaserad renovering","h1_line1":"Renovering för en ny era","h1_accent":"med fabrikstillverkade isolerade element.","lead":"Vid tillverkningen av fasadelement bygger EstNor på omfattande kunskap och decennier av erfarenhet, och erbjuder bästa kompetens för att höja byggnaders energieffektivitet.","cta_primary":"Kontakta oss","cta_secondary":"Se fasadelementet"},"why_left":{"h2":"Varför fabrikstillverkade element","items":["90 % av fasadarbetet utförs i fabriken, i en kontrollerad miljö","Förtillverkade element gör arbetet på plats betydligt effektivare","Arbetet på plats kräver ingen byggnadsställning","Ett tryggt och bekvämt renoveringssätt för de boende","Lösningen uppfyller brandsäkerhetskraven"]},"why_right":{"h2":"EstNor erbjuder","items":["Mätning av byggnaden och utdragsprovning av infästningar","Konstruktionsprojektering (BIM-modell)","Fabrikstillverkning av elementen","Ventilationskanaler monterade i elementen redan i fabriken","Transport från fabriken till byggplatsen","Montage av elementen samt för- och efterarbete på plats"]},"steps":{"eyebrow":"Så här fungerar det","h2":"Från byggnadsskanning till monterad fasad","items":[{"title":"Skanning","desc":"Den befintliga byggnaden 3D-skannas från marken och med drönare — resultatet är ett detaljerat punktmoln."},{"title":"Modellering","desc":"En BIM-modell skapas från punktmolnet, som ligger till grund för de nya fasadelementen."},{"title":"Förberedelse & hörnelement","desc":"Konsoler och en bottenskena monteras, därefter de första elementen i byggnadens hörn."},{"title":"Montage & färdigställande","desc":"Elementen monteras rad för rad, därefter ventilation, trapphus, dagvattensystem och takanslutning."}]},"funding_left":{"eyebrow":"KredEx renoveringsstöd 2022–2027","h2":"Ett statligt stödprogram","p1":"KredEx stödprogram finansierar en omfattande renovering av flerbostadshus eller byte av uppvärmningssystem till en lösning baserad på förnybar energi. Mer information: KredEx.ee.","p2":"EstNor deltog mycket framgångsrikt i det första KredEx-pilotprojektet (2022) och säkrade tillverkningen av fasadelement till 12 flerbostadshus — alla byggda på trästomme, med mineralullsisolering, nya PVC-fönster och fasadytan redan applicerad i fabriken. EstNor är den första och volymmässigt största tillverkaren i programmet."},"funding_right":{"eyebrow":"Hastighet som räknas","h2":"3–4 veckor, inte nästan ett år","p":"Medan isolering av en 5-våningsbyggnad med 5 trapphus på plats med cellplast kan ta nästan ett år, klär vårt fabrikstillverkade fasadelement samma byggnads fasad på bara 3–4 veckor. Ingen byggnadsställning behövs — den skulle blockera de boendes utsikt och utgöra en säkerhetsrisk under hela renoveringen.","callout_label":"Resultat:","callout_text":"gamla flerbostadshus får snabbt bättre energieffektivitet, byggtiden kortas och byggnadens livslängd förlängs."},"explore":{"eyebrow":"Läs mer","h2":"Utforska vidare","cards":[{"title":"Fasad- och takelement","desc":"Hur fasadelementet är uppbyggt — från mätning till färdig yta.","href":"facade-elements.php"},{"title":"Genomförda projekt","desc":"12 flerbostadshus renoverade runt om i Estland inom ramen för KredEx-programmet.","href":"../projects.php"}]},"cta":{"h2":"Planerar du att renovera ett flerbostadshus?","body":"Skicka oss byggnadens nyckeldata — byggår, antal lägenheter, fasadyta — så återkommer vi med en första bedömning.","button":"Kontakta oss"}}') ON DUPLICATE KEY UPDATE content = VALUES(content);
INSERT INTO i18n_strings (lang_code, section, content) VALUES ('nb', 'page:serial-renovation', '{"meta":{"title":"Modernisering av leilighetsbygg | EstNor","desc":"EstNor produserer isolerte fasadeelementer for fabrikkbasert modernisering av leilighetsbygg — første og største produsent i KredEx pilotprogram."},"hero":{"crumb":"Forsiden","label":"Modernisering av leilighetsbygg","eyebrow":"Fabrikkbasert rehabilitering","h1_line1":"Rehabilitering for en ny æra","h1_accent":"med fabrikkproduserte isolerte elementer.","lead":"I produksjonen av fasadeelementer bygger EstNor på omfattende kunnskap og tiår med erfaring, og tilbyr den beste kompetansen for å heve bygningers energieffektivitet.","cta_primary":"Kontakt oss","cta_secondary":"Se fasadeelementet"},"why_left":{"h2":"Hvorfor fabrikkproduserte elementer","items":["90 % av fasadearbeidet utføres i fabrikken, i et kontrollert miljø","Prefabrikkerte elementer gjør arbeidet på byggeplassen langt mer effektivt","Arbeidet på byggeplassen krever ikke stillas","En trygg og bekvem rehabiliteringsmetode for beboerne","Løsningen oppfyller brannsikkerhetskravene"]},"why_right":{"h2":"EstNor tilbyr","items":["Oppmåling av bygget og utrivingstesting av festeanordninger","Konstruktiv prosjektering (BIM-modell)","Fabrikkproduksjon av elementene","Ventilasjonskanaler montert i elementene allerede i fabrikken","Transport fra fabrikken til byggeplassen","Montasje av elementene samt for- og etterarbeid på stedet"]},"steps":{"eyebrow":"Slik fungerer det","h2":"Fra bygningsskanning til montert fasade","items":[{"title":"Skanning","desc":"Det eksisterende bygget 3D-skannes fra bakken og med drone — resultatet er en detaljert punktsky."},{"title":"Modellering","desc":"En BIM-modell lages fra punktskyen, som de nye fasadeelementene prosjekteres etter."},{"title":"Forberedelse & hjørneelementer","desc":"Konsoller og grunnskinne monteres, deretter de første elementene i bygningens hjørner."},{"title":"Montasje & ferdigstillelse","desc":"Elementene monteres rad for rad, deretter ventilasjon, trapperom, regnvannssystem og takforbindelse."}]},"funding_left":{"eyebrow":"KredEx rehabiliteringsstøtte 2022–2027","h2":"En statlig støtteordning","p1":"KredEx-støtteordningen finansierer en helhetlig rehabilitering av leilighetsbygg eller utskifting av oppvarmingssystemet til en løsning basert på fornybar energi. Mer informasjon: KredEx.ee.","p2":"EstNor deltok svært vellykket i det første KredEx-pilotprosjektet (2022) og sikret produksjonen av fasadeelementer for 12 leilighetsbygg — alle bygget på trekonstruksjon, med mineralullisolasjon, nye PVC-vinduer og fasadeoverflaten allerede påført i fabrikken. EstNor er den første og volummessig største produsenten i programmet."},"funding_right":{"eyebrow":"Hastighet som teller","h2":"3–4 uker, ikke nesten et år","p":"Mens isolering av et 5-etasjers bygg med 5 oppganger på stedet med ekspandert polystyren kan ta nesten et år, kler vårt fabrikkproduserte fasadeelement samme bygnings fasade på bare 3–4 uker. Stillas er ikke nødvendig — det ville blokkert beboernes utsikt og utgjort en sikkerhetsrisiko gjennom hele rehabiliteringen.","callout_label":"Resultat:","callout_text":"gamle leilighetsbygg får raskt bedre energieffektivitet, byggetiden forkortes, og bygningens levetid forlenges."},"explore":{"eyebrow":"Les mer","h2":"Utforsk videre","cards":[{"title":"Fasade- og takelementer","desc":"Hvordan fasadeelementet er bygd opp — fra oppmåling til ferdig overflate.","href":"facade-elements.php"},{"title":"Gjennomførte prosjekter","desc":"12 leilighetsbygg rehabilitert over hele Estland gjennom KredEx-programmet.","href":"../projects.php"}]},"cta":{"h2":"Planlegger du å rehabilitere et leilighetsbygg?","body":"Send oss nøkkeltallene for bygget — byggeår, antall leiligheter, fasadeareal — så kommer vi tilbake med en første vurdering.","button":"Kontakt oss"}}') ON DUPLICATE KEY UPDATE content = VALUES(content);
