-- db/seed.sql — generated by db/generate_seed.php from content/db/*.json.
-- Import via phpMyAdmin (hPanel -> Databases -> phpMyAdmin -> your DB -> Import)
-- as an alternative to running `php db/migrate.php` when SSH/CLI isn't available.
-- Safe to re-import any time content/db/*.json changes and this file is regenerated.

CREATE TABLE IF NOT EXISTS languages (
  code       VARCHAR(5)  NOT NULL PRIMARY KEY,
  name       VARCHAR(40) NOT NULL,
  is_default TINYINT(1)  NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS i18n_strings (
  lang_code  VARCHAR(5)   NOT NULL,
  section    VARCHAR(80)  NOT NULL,
  content    LONGTEXT     NOT NULL,
  updated_at TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (lang_code, section)
);














